概述提示工程是发挥大模型能力的关键技术，本文介绍从基础到高级的提示技巧。 提示工程核心技巧零样本 vs 少样本flowchart TB subgraph Zero-Shot ZS[零样本提示] ZS --> QUERY[直接提问] end subgraph Few-Shot FS[少样本提示] FS --> EX1[示例1] FS --> EX2[示例2] FS --> EX3[示例3] EX1 --> QUERY2[最终问题] end 思维链提示12345678910111213141516171819class ChainOfThought: &quot;&quot;&quot;思维链提示&quot;&quot;&quot; def zero_shot_cot(self, question): &quot;&quot;&quot;零样本思维链&quot;&quot;&quot; prompt = f&quot;&quot;&quot;问题: &#123;question&#125;请逐步思考，然后给出答案。&quot;&quot;&quot; return self.llm.generate(prompt) def few_shot_cot(self, question, examples): &quot;&quot;&quot;少样本思维链&quot;&quot;&quot; prompt = &quot;请逐步推理：

&quot; for ex in examples: prompt += f&quot;问题: &#123;ex[&#x27;q&#x27;]&#125;
思考: &#123;ex[&#x27;thought&#x27;]&#125;
答案: &#123;ex[&#x27;a&#x27;]&#125;

&quot; prompt += f&quot;问题: &#123;question&#125;
思考:&quot; return self.llm.generate(prompt) 高级提示模式 模式 适用场景 效果提升 CoT 推理任务 +30% Few-Shot 格式要求 +50% ReAct 工具使用 +100% Tree-of-Thought 复杂决策 +40% 总结mindmap root((提示工程)) 基础技巧 清晰指令 格式指定 角色设定 进阶技巧 思维链 少样本学习 分解问题 高级技巧 ReAct Tree-of-Thought 自动提示优化 掌握提示工程能显著提升大模型的使用效率和输出质量。

RAG技术原理：大模型检索增强生成详解引言检索增强生成（Retrieval-Augmented Generation, RAG）是一种将大规模语言模型与外部知识检索相结合的技术。RAG解决了大模型的两大核心问题：知识过时和幻觉问题。本文将深入解析RAG的技术原理、实现方法和最佳实践。 为什么需要RAG大语言模型的局限性 问题 说明 影响 知识截止 训练数据有时间限制 无法回答最新问题 幻觉 可能生成看似合理但错误的答案 可靠性降低 长尾知识 对稀有领域知识覆盖不足 专业领域应用受限 领域知识 缺乏特定行业的专业知识 企业应用受限 实时信息 无法访问实时数据和新闻 应用场景受限 RAG的核心思想RAG通过”检索-增强-生成”的流程来解决上述问题： 1用户问题 → 检索相关文档 → 将文档加入Prompt → LLM生成答案 RAG系统架构整体流程1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980818283848586878889909192939495class RAGSystem: &quot;&quot;&quot; RAG系统完整架构 &quot;&quot;&quot; def __init__(self, config): # 1. 文档处理组件 self.document_loader = DocumentLoader(config[&#x27;loader_type&#x27;]) self.text_splitter = TextSplitter( chunk_size=config[&#x27;chunk_size&#x27;], chunk_overlap=config[&#x27;chunk_overlap&#x27;] ) # 2. 向量化组件 self.embedding_model = EmbeddingModel(config[&#x27;embedding_model&#x27;]) # 3. 向量存储 self.vector_store = VectorStore( config[&#x27;vector_store_type&#x27;], config[&#x27;vector_store_path&#x27;] ) # 4. 检索器 self.retriever = Retriever( top_k=config[&#x27;top_k&#x27;], similarity_threshold=config[&#x27;similarity_threshold&#x27;] ) # 5. 生成器 self.llm = LLMModel(config[&#x27;llm_type&#x27;], config[&#x27;llm_config&#x27;]) def index_documents(self, documents): &quot;&quot;&quot;构建索引&quot;&quot;&quot; # 文档加载 docs = self.document_loader.load(documents) # 文本分块 chunks = self.text_splitter.split(docs) # 向量化 embeddings = self.embedding_model.encode(chunks) # 存储 self.vector_store.add(chunks, embeddings) def retrieve(self, query, top_k=5): &quot;&quot;&quot;检索相关文档&quot;&quot;&quot; # 查询向量化 query_embedding = self.embedding_model.encode([query]) # 相似度搜索 results = self.vector_store.search(query_embedding, top_k) return results def generate(self, query, context_docs): &quot;&quot;&quot;增强生成&quot;&quot;&quot; # 构建Prompt prompt = self.build_prompt(query, context_docs) # LLM生成 response = self.llm.generate(prompt) return response def build_prompt(self, query, context_docs): &quot;&quot;&quot;构建RAG Prompt&quot;&quot;&quot; context = &quot;

&quot;.join([ f&quot;文档 &#123;i+1&#125;:
&#123;doc.content&#125;&quot; for i, doc in enumerate(context_docs) ]) prompt = f&quot;&quot;&quot;基于以下参考文档回答问题。如果文档中没有相关信息，请说明不知道。参考文档：&#123;context&#125;问题：&#123;query&#125;回答：&quot;&quot;&quot; return prompt def query(self, question): &quot;&quot;&quot;完整RAG流程&quot;&quot;&quot; # 1. 检索 retrieved_docs = self.retrieve(question, top_k=self.config[&#x27;top_k&#x27;]) # 2. 生成 response = self.generate(question, retrieved_docs) return &#123; &#x27;answer&#x27;: response, &#x27;sources&#x27;: retrieved_docs &#125; 文档处理与分块策略文档加载器123456789101112131415161718192021222324252627282930313233343536class DocumentLoader: &quot;&quot;&quot;多格式文档加载器&quot;&quot;&quot; def __init__(self, loader_type=&#x27;pdf&#x27;): self.loader_type = loader_type def load(self, file_path): if self.loader_type == &#x27;pdf&#x27;: return self._load_pdf(file_path) elif self.loader_type == &#x27;docx&#x27;: return self._load_docx(file_path) elif self.loader_type == &#x27;html&#x27;: return self._load_html(file_path) elif self.loader_type == &#x27;markdown&#x27;: return self._load_markdown(file_path) else: raise ValueError(f&quot;Unsupported format: &#123;self.loader_type&#125;&quot;) def _load_pdf(self, file_path): &quot;&quot;&quot;PDF加载&quot;&quot;&quot; from pypdf import PdfReader reader = PdfReader(file_path) documents = [] for page_num, page in enumerate(reader.pages): text = page.extract_text() documents.append(&#123; &#x27;content&#x27;: text, &#x27;metadata&#x27;: &#123; &#x27;source&#x27;: file_path, &#x27;page&#x27;: page_num + 1 &#125; &#125;) return documents 分块策略1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162class TextSplitter: &quot;&quot;&quot;文本分块器&quot;&quot;&quot; def __init__(self, chunk_size=500, chunk_overlap=50): self.chunk_size = chunk_size self.chunk_overlap = chunk_overlap def split(self, documents): &quot;&quot;&quot;分割文档为小块&quot;&quot;&quot; chunks = [] for doc in documents: text = doc[&#x27;content&#x27;] metadata = doc[&#x27;metadata&#x27;] # 使用滑动窗口分割 start = 0 while start &lt; len(text): end = start + self.chunk_size chunk_text = text[start:end] chunks.append(&#123; &#x27;content&#x27;: chunk_text, &#x27;metadata&#x27;: metadata, &#x27;start_char&#x27;: start, &#x27;end_char&#x27;: end &#125;) start += (self.chunk_size - self.chunk_overlap) return chunks def split_by_semantic(self, text, model): &quot;&quot;&quot; 语义分块：根据语义边界分割 &quot;&quot;&quot; # 句子级别分割 sentences = self._split_sentences(text) # 构建句子嵌入 embeddings = model.encode(sentences) # 基于嵌入相似度决定分块点 chunks = [] current_chunk = [sentences[0]] for i in range(1, len(sentences)): # 检查与前一个句子的相似度 similarity = cosine_similarity( embeddings[i-1], embeddings[i] ) if similarity &gt; 0.7: # 语义相近，合并 current_chunk.append(sentences[i]) else: # 语义跳跃，开始新块 chunks.append(&#x27; &#x27;.join(current_chunk)) current_chunk = [sentences[i]] if current_chunk: chunks.append(&#x27; &#x27;.join(current_chunk)) return chunks 向量化与 EmbeddingEmbedding模型选择 模型 维度 特点 适用场景 OpenAI text-embedding-ada-002 1536 通用强 通用场景 BGE 1024 中英双语 多语言 M3E 768 中文优化 中文场景 Instructor 768 指令驱动 领域特定 1234567891011121314151617181920212223242526272829303132333435class EmbeddingModel: &quot;&quot;&quot;Embedding模型封装&quot;&quot;&quot; def __init__(self, model_name=&#x27;bge-large-zh-v1.5&#x27;): self.model_name = model_name self.model = self._load_model(model_name) self.tokenizer = self._load_tokenizer(model_name) def encode(self, texts, batch_size=32): &quot;&quot;&quot;批量编码&quot;&quot;&quot; embeddings = [] for i in range(0, len(texts), batch_size): batch = texts[i:i + batch_size] inputs = self.tokenizer( batch, padding=True, truncation=True, max_length=512, return_tensors=&#x27;pt&#x27; ) with torch.no_grad(): outputs = self.model(**inputs) # 使用[CLS] token或均值池化 batch_embeddings = outputs.last_hidden_state.mean(dim=1) embeddings.append(batch_embeddings.numpy()) return np.vstack(embeddings) def encode_query(self, query): &quot;&quot;&quot;编码查询（可能需要特殊处理）&quot;&quot;&quot; return self.encode([query])[0] 向量数据库主流向量数据库对比 数据库 特点 适用规模 部署方式 Milvus 高性能，开源 十亿级 云&#x2F;本地 Qdrant Rust实现，高效 亿级 云&#x2F;本地 Chroma 轻量级，易用 百万级 嵌入式 Pinecone 云原生 任意规模 仅云 Weaviate 混合搜索 千万级 云&#x2F;本地 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364class VectorStore: &quot;&quot;&quot;向量存储封装&quot;&quot;&quot; def __init__(self, store_type=&#x27;milvus&#x27;, connection_params=None): self.store_type = store_type if store_type == &#x27;milvus&#x27;: from pymilvus import connections, Collection connections.connect(**connection_params) self.collection = Collection(connection_params[&#x27;collection_name&#x27;]) elif store_type == &#x27;qdrant&#x27;: from qdrant_client import QdrantClient self.client = QdrantClient(**connection_params) elif store_type == &#x27;chroma&#x27;: import chromadb self.client = chromadb.Client() def add(self, chunks, embeddings, ids=None): &quot;&quot;&quot;添加向量到数据库&quot;&quot;&quot; if ids is None: ids = [str(i) for i in range(len(chunks))] if self.store_type == &#x27;milvus&#x27;: self.collection.insert([ &#123; &#x27;id&#x27;: id_, &#x27;vector&#x27;: embedding, &#x27;content&#x27;: chunk[&#x27;content&#x27;], &#x27;metadata&#x27;: chunk[&#x27;metadata&#x27;] &#125; for id_, embedding, chunk in zip(ids, embeddings, chunks) ]) elif self.store_type == &#x27;chroma&#x27;: self.client.add( ids=ids, embeddings=embeddings, documents=[c[&#x27;content&#x27;] for c in chunks], metadatas=[c[&#x27;metadata&#x27;] for c in chunks] ) def search(self, query_embedding, top_k=5, similarity_threshold=0.7): &quot;&quot;&quot;相似度搜索&quot;&quot;&quot; if self.store_type == &#x27;milvus&#x27;: results = self.collection.search( data=[query_embedding], anns_field=&#x27;vector&#x27;, top_k=top_k, param=&#123;&#x27;metric_type&#x27;: &#x27;IP&#x27;&#125; # 内积相似度 ) return [r for r in results[0] if r.score &gt;= similarity_threshold] elif self.store_type == &#x27;chroma&#x27;: results = self.client.query( query_embeddings=[query_embedding], n_results=top_k ) return results 检索策略基础检索12345678910111213141516class NaiveRetriever: &quot;&quot;&quot;简单向量检索&quot;&quot;&quot; def __init__(self, vector_store, embedding_model, top_k=5): self.vector_store = vector_store self.embedding_model = embedding_model self.top_k = top_k def retrieve(self, query): # 向量化查询 query_embedding = self.embedding_model.encode_query(query) # 搜索 results = self.vector_store.search(query_embedding, self.top_k) return results 混合检索123456789101112131415161718192021222324252627282930313233343536373839404142434445464748class HybridRetriever: &quot;&quot;&quot;混合检索：向量+关键词&quot;&quot;&quot; def __init__(self, vector_store, bm25_index, embedding_model, top_k=10, alpha=0.5): self.vector_store = vector_store self.bm25_index = bm25_index self.embedding_model = embedding_model self.top_k = top_k self.alpha = alpha # 向量权重 def retrieve(self, query): # 1. 向量检索 query_embedding = self.embedding_model.encode_query(query) vector_results = self.vector_store.search( query_embedding, self.top_k * 2 ) # 2. BM25检索 bm25_results = self.bm25_index.search(query, self.top_k * 2) # 3. RRF融合 fused_scores = self._reciprocal_rank_fusion( vector_results, bm25_results ) # 4. 返回top_k return sorted(fused_scores, key=lambda x: x[&#x27;score&#x27;], reverse=True)[:self.top_k] def _reciprocal_rank_fusion(self, results_list, k=60): &quot;&quot;&quot;RRF融合算法&quot;&quot;&quot; scores = &#123;&#125; for results in results_list: for rank, result in enumerate(results): doc_id = result[&#x27;id&#x27;] rrf_score = 1 / (k + rank + 1) if doc_id not in scores: scores[doc_id] = &#123; &#x27;doc&#x27;: result, &#x27;score&#x27;: 0 &#125; scores[doc_id][&#x27;score&#x27;] += rrf_score return list(scores.values()) 重排序（Reranker）123456789101112131415161718192021222324252627class Reranker: &quot;&quot;&quot;重排序模型&quot;&quot;&quot; def __init__(self, model_name=&#x27;cross-encoder&#x27;): self.model = self._load_model(model_name) def rerank(self, query, documents, top_k=5): &quot;&quot;&quot; 使用Cross-Encoder重排序 &quot;&quot;&quot; # 构建句子对 pairs = [(query, doc[&#x27;content&#x27;]) for doc in documents] # 计算相关性分数 scores = self.model.predict(pairs) # 排序 doc_scores = list(zip(documents, scores)) doc_scores.sort(key=lambda x: x[1], reverse=True) # 返回top_k reranked = [] for doc, score in doc_scores[:top_k]: doc[&#x27;rerank_score&#x27;] = score reranked.append(doc) return reranked 高级RAG技术1. 子问题分解1234567891011121314151617181920212223242526272829303132333435class SubQuestionRetriever: &quot;&quot;&quot;子问题分解检索&quot;&quot;&quot; def __init__(self, llm, retriever): self.llm = llm self.retriever = retriever def decompose(self, query): &quot;&quot;&quot;将复杂问题分解为子问题&quot;&quot;&quot; prompt = f&quot;&quot;&quot;将以下问题分解为多个简单的子问题：问题：&#123;query&#125;子问题：&quot;&quot;&quot; response = self.llm.generate(prompt) sub_questions = self._parse_sub_questions(response) return sub_questions def retrieve_with_decomposition(self, query): &quot;&quot;&quot;分解+检索&quot;&quot;&quot; # 分解问题 sub_questions = self.decompose(query) # 分别检索 all_results = [] for sq in sub_questions: results = self.retriever.retrieve(sq) all_results.extend(results) # 去重和排序 unique_results = self._deduplicate(all_results) return unique_results 2. 自适应检索123456789101112131415161718192021222324252627282930313233343536class AdaptiveRAG: &quot;&quot;&quot;自适应检索策略&quot;&quot;&quot; def __init__(self, llm, retrievers): self.llm = llm self.retrievers = retrievers # 不同策略的检索器 def decide_retrieval_strategy(self, query): &quot;&quot;&quot;决定检索策略&quot;&quot;&quot; prompt = f&quot;&quot;&quot;分析以下查询，决定最佳检索策略：查询：&#123;query&#125;策略选项：1. web_search - 需要最新信息2. vector_search - 需要从知识库检索3. hybrid - 需要结合两者4. direct_answer - 可以直接回答决策：&quot;&quot;&quot; decision = self.llm.generate(prompt) return self._parse_decision(decision) def query(self, question): &quot;&quot;&quot;自适应查询&quot;&quot;&quot; strategy = self.decide_retrieval_strategy(question) if strategy == &#x27;vector_search&#x27;: return self.retrievers[&#x27;vector&#x27;].retrieve(question) elif strategy == &#x27;web_search&#x27;: return self.retrievers[&#x27;web&#x27;].search(question) elif strategy == &#x27;hybrid&#x27;: return self.retrievers[&#x27;hybrid&#x27;].retrieve(question) else: return [] 评估指标123456789101112131415161718192021222324252627282930313233343536373839404142class RAGEvaluator: &quot;&quot;&quot;RAG系统评估&quot;&quot;&quot; def evaluate(self, test_set, rag_system): &quot;&quot;&quot; 评估RAG系统 测试指标： - 检索召回率 - 生成质量 (BLEU, ROUGE) - 答案正确性 - 引用准确率 &quot;&quot;&quot; results = [] for item in test_set: question = item[&#x27;question&#x27;] expected_answer = item[&#x27;answer&#x27;] # RAG查询 response = rag_system.query(question) # 评估 metrics = &#123; &#x27;faithfulness&#x27;: self.compute_faithfulness( response[&#x27;answer&#x27;], response[&#x27;sources&#x27;] ), &#x27;answer_relevancy&#x27;: self.compute_answer_relevancy( question, response[&#x27;answer&#x27;] ), &#x27;context_recall&#x27;: self.compute_context_recall( expected_answer, response[&#x27;sources&#x27;] ), &#x27;context_precision&#x27;: self.compute_context_precision( expected_answer, response[&#x27;sources&#x27;] ) &#125; results.append(metrics) # 汇总 return self._aggregate_metrics(results) 总结RAG是当前大模型应用的主流架构，通过将外部知识检索与大模型生成相结合，有效解决了知识时效性和幻觉问题。随着向量数据库、Embedding模型和检索策略的不断优化，RAG系统的性能正在持续提升。 推荐阅读： 《Retrieval-Augmented Generation for Knowledge-Intensive NLP Tasks》 LangChain官方文档 向量数据库对比分析

引言Mistral AI是一家成立于2023年的法国AI公司，其发布的Mistral 7B和Mixtral 8x7B模型在开源社区引起了巨大反响。本文将深入分析Mistral系列模型的技术架构，包括其采用的滑动窗口注意力、滚动缓存等创新技术。 Mistral 7B技术解析1. 模型架构123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110import torchimport torch.nn as nnimport mathclass MistralConfig: &quot;&quot;&quot; Mistral 7B配置 &quot;&quot;&quot; def __init__(self): self.vocab_size = 32000 self.hidden_size = 4096 self.intermediate_size = 14336 self.num_hidden_layers = 32 self.num_attention_heads = 32 self.num_key_value_heads = 8 # GQA self.hidden_act = &quot;silu&quot; self.max_position_embeddings = 32768 self.rope_theta = 10000.0 self.sliding_window = 4096 # 滑动窗口注意力 self.rope_scaling = &#123;&quot;type&quot;: &quot;linear&quot;, &quot;factor&quot;: 2.0&#125;class MistralAttention(nn.Module): &quot;&quot;&quot; Mistral注意力机制 支持滑动窗口和Grouped Query Attention &quot;&quot;&quot; def __init__(self, config): super().__init__() self.hidden_size = config.hidden_size self.num_heads = config.num_attention_heads self.head_dim = config.hidden_size // config.num_heads self.num_key_value_heads = config.num_key_value_heads self.sliding_window = config.sliding_window # GQA: K/V头数少于Q头数 self.q_proj = nn.Linear(config.hidden_size, config.num_attention_heads * self.head_dim) self.k_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim) self.v_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim) self.o_proj = nn.Linear(config.num_attention_heads * self.head_dim, config.hidden_size) # RoPE self.rotary_emb = MistralRotaryEmbedding(self.head_dim, config.max_position_embeddings) def forward(self, x, attention_mask=None, position_ids=None): B, T, C = x.shape # QKV投影 q = self.q_proj(x).reshape(B, T, self.num_heads, self.head_dim) k = self.k_proj(x).reshape(B, T, self.num_key_value_heads, self.head_dim) v = self.v_proj(x).reshape(B, T, self.num_key_value_heads, self.head_dim) # 应用RoPE q, k = self.rotary_emb(q, k, position_ids) # Grouped Query Attention q = q.reshape(B, T, self.num_heads, self.head_dim).transpose(1, 2) k = k.reshape(B, T, self.num_key_value_heads, self.head_dim).transpose(1, 2) v = v.reshape(B, T, self.num_key_value_heads, self.head_dim).transpose(1, 2) # 扩展K/V到Q头数 k = self._repeat_kv(k, self.num_heads // self.num_key_value_heads) v = self._repeat_kv(v, self.num_heads // self.num_key_value_heads) # 滑动窗口掩码 if self.sliding_window and T &gt; self.sliding_window: # 创建因果掩码 mask = torch.triu(torch.ones(T, T, device=x.device), 1).bool() # 滑动窗口掩码：只关注最近sliding_window个token mask = mask | (torch.arange(T, device=x.device).unsqueeze(0) &lt; T - self.sliding_window) if attention_mask is not None: mask = mask &amp; attention_mask else: mask = attention_mask # 注意力计算 attn = torch.nn.functional.scaled_dot_product_attention( q, k, v, attn_mask=mask ) return self.o_proj(attn.transpose(1, 2).reshape(B, T, C)) def _repeat_kv(self, x, n_rep): &quot;&quot;&quot;重复K/V以匹配Q头数&quot;&quot;&quot; B, n_kv_heads, T, head_dim = x.shape if n_rep == 1: return x return x[:, :, None, :, :].expand(B, n_kv_heads, n_rep, T, head_dim).reshape(B, n_kv_heads * n_rep, T, head_dim)class MistralRotaryEmbedding(nn.Module): &quot;&quot;&quot; 旋转位置编码 &quot;&quot;&quot; def __init__(self, dim, max_position=32768, base=10000): super().__init__() inv_freq = 1.0 / (base ** (torch.arange(0, dim, 2).float() / dim)) self.register_buffer(&quot;inv_freq&quot;, inv_freq) def forward(self, q, k, position_ids): T = position_ids.shape[1] freqs = torch.einsum(&quot;i,j-&gt;ij&quot;, position_ids[0].float(), self.inv_freq) emb = torch.cat((freqs, freqs), dim=-1) cos = emb.cos() sin = emb.sin() return self._rotate(q, cos, sin), self._rotate(k, cos, sin) def _rotate(self, x, cos, sin): x1, x2 = x[..., :x.shape[-1]//2], x[..., x.shape[-1]//2:] return torch.cat((-x2, x1), dim=-1) * cos + x1 * (-sin) + x2 * cos 2. 滑动窗口注意力1234567891011121314151617181920212223242526272829303132333435363738class SlidingWindowAttention: &quot;&quot;&quot; 滑动窗口注意力机制 时间复杂度从O(T²)降低到O(T*W) W为窗口大小 &quot;&quot;&quot; def __init__(self, window_size=4096): self.window_size = window_size def compute_attention(self, q, k, v): &quot;&quot;&quot; 计算滑动窗口注意力 &quot;&quot;&quot; B, num_heads, T, head_dim = q.shape # 准备输出 output = torch.zeros_like(q) # 分块处理 for i in range(0, T, self.window_size): # 获取当前窗口 end = min(i + self.window_size, T) # 窗口内的K, V k_window = k[:, :, i:end, :] v_window = v[:, :, i:end, :] # 当前窗口的Q q_window = q[:, :, i:end, :] # 计算注意力 attn = torch.matmul(q_window, k_window.transpose(-2, -1)) / math.sqrt(head_dim) attn = torch.softmax(attn, dim=-1) # 应用注意力 output[:, :, i:end, :] = torch.matmul(attn, v_window) return output Mixtral 8x7B：混合专家模型1. MoE架构123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475class MixtralMoE(nn.Module): &quot;&quot;&quot; Mixtral 8x7B 混合专家架构 8个专家，每次激活2个 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.num_experts = 8 self.top_k = 2 # 激活的专家数 # 专家路由器 self.gate = nn.Linear(config.hidden_size, self.num_experts) # 专家网络 self.experts = nn.ModuleList([ MistralMoEBlock(config) for _ in range(self.num_experts) ]) def forward(self, x): &quot;&quot;&quot; MoE前向传播 &quot;&quot;&quot; B, T, C = x.shape # 计算每个专家的门控值 gate_logits = self.gate(x) gate_probs = torch.softmax(gate_logits, dim=-1) # 选择top-k专家 top_k_probs, top_k_indices = torch.topk(gate_probs, self.top_k, dim=-1) # 归一化 top_k_probs = top_k_probs / top_k_probs.sum(dim=-1, keepdim=True) # 初始化输出 output = torch.zeros_like(x) # 累加每个专家的贡献 for expert_idx in range(self.num_experts): # 找出选择该专家的token mask = (top_k_indices == expert_idx) # 计算该专家的权重 weights = torch.zeros(B, T, device=x.device) for k in range(self.top_k): expert_mask = (top_k_indices[:, :, k] == expert_idx) weights += top_k_probs[:, :, k] * expert_mask.float() # 通过专家处理 expert_output = self.experts[expert_idx](x) # 加权累加 output += expert_output * weights.unsqueeze(-1) return outputclass MistralMoEBlock(nn.Module): &quot;&quot;&quot; MoE专家块 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.block = nn.ModuleDict(&#123; &quot;w1&quot;: nn.Linear(config.hidden_size, config.intermediate_size, bias=False), &quot;w2&quot;: nn.Linear(config.intermediate_size, config.hidden_size, bias=False), &quot;w3&quot;: nn.Linear(config.hidden_size, config.intermediate_size, bias=False) &#125;) def forward(self, x): &quot;&quot;&quot; SwiGLU激活 &quot;&quot;&quot; return self.block[&quot;w2&quot;]( torch.nn.functional.silu(self.block[&quot;w1&quot;](x)) * self.block[&quot;w3&quot;](x) ) Mistral模型部署1. HuggingFace Transformers部署123456789101112131415161718192021222324252627282930313233343536373839404142434445from transformers import AutoModelForCausalLM, AutoTokenizerimport torchclass MistralDeployer: def __init__(self, model_path: str): self.tokenizer = AutoTokenizer.from_pretrained(model_path) self.model = AutoModelForCausalLM.from_pretrained( model_path, torch_dtype=torch.float16, device_map=&quot;auto&quot; ) def generate(self, prompt: str, max_tokens: int = 256, temperature: float = 0.7, top_p: float = 0.9): &quot;&quot;&quot;生成文本&quot;&quot;&quot; inputs = self.tokenizer(prompt, return_tensors=&quot;pt&quot;).to(&quot;cuda&quot;) outputs = self.model.generate( **inputs, max_new_tokens=max_tokens, do_sample=True, temperature=temperature, top_p=top_p, pad_token_id=self.tokenizer.eos_token_id ) return self.tokenizer.decode(outputs[0], skip_special_tokens=True) def chat(self, messages: list) -&gt; str: &quot;&quot;&quot;对话接口&quot;&quot;&quot; # 构建prompt prompt = self._build_chat_prompt(messages) return self.generate(prompt) def _build_chat_prompt(self, messages: list) -&gt; str: &quot;&quot;&quot;构建对话prompt&quot;&quot;&quot; prompt = &quot;&quot; for msg in messages: if msg[&#x27;role&#x27;] == &#x27;system&#x27;: prompt += f&quot;[INST] &lt;&lt;SYS&gt;&gt;
&#123;msg[&#x27;content&#x27;]&#125;
&lt;&lt;/SYS&gt;&gt;
[/INST]
&quot; elif msg[&#x27;role&#x27;] == &#x27;user&#x27;: prompt += f&quot;[INST] &#123;msg[&#x27;content&#x27;]&#125; [/INST]&quot; elif msg[&#x27;role&#x27;] == &#x27;assistant&#x27;: prompt += f&quot;&#123;msg[&#x27;content&#x27;]&#125;
&quot; return prompt 2. vLLM高性能部署12345678# 使用vLLM部署Mistralpip install vllmpython -m vllm.entrypoints.openai.api_server \ --model mistralai/Mistral-7B-Instruct-v0.1 \ --served-model-name mistral \ --port 8000 \ --tensor-parallel-size 1 3. ollama本地部署123456789# 使用ollama部署ollama run mistral# API调用curl http://localhost:11434/api/generate -d &#x27;&#123; &quot;model&quot;: &quot;mistral&quot;, &quot;prompt&quot;: &quot;解释量子计算的基本原理&quot;, &quot;stream&quot;: false&#125;&#x27; Mistral性能对比Benchmark结果 模型 MMLU HellaSwag TruthfulQA Winogrande Mistral 7B 60.1% 83.0% 42.9% 74.8% Llama 2 7B 54.8% 79.4% 39.4% 72.3% Llama 2 13B 59.2% 81.8% 43.6% 74.8% Mixtral 8x7B 68.4% 85.7% 48.1% 76.8% 总结Mistral AI凭借创新的滑动窗口注意力、GQA和MoE等技术，在保持高性能的同时大幅降低了计算成本。Mistral 7B和Mixtral 8x7B的开源，为开发者和企业提供了强大的本地部署选择。随着Mistral生态的持续发展，我们期待看到更多基于Mistral的创新应用。 参考资源 Mistral AI官网 Mistral 7B论文 Mixtral论文 HuggingFace Mistral

引言在边缘设备上部署大语言模型是2023年的重要研究方向。NVIDIA Jetson系列平台凭借强大的GPU算力，成为嵌入式AI的理想选择。本文将详细介绍如何在Jetson Nano、Xavier NX等设备上使用TensorRT-LLM部署和优化大模型。 Jetson平台概述1. Jetson系列对比 型号 GPU AI算力 内存 功耗 适用场景 Jetson Nano 128-core Maxwell 0.5 TFLOPS 4GB 5-10W 轻量推理 Jetson Xavier NX 384-core Volta 21 TFLOPS 8&#x2F;16GB 10-15W 中量推理 Jetson AGX Orin 2048-core Ampere 275 TOPS 32&#x2F;64GB 15-60W 大模型部署 2. 环境准备123456789101112131415# 刷写JetPack# 下载SDK Manager: https://developer.nvidia.com/embedded/jetpack# 基础环境设置sudo apt-get updatesudo apt-get install -y python3-pipsudo apt-get install -y libopenmpi-dev# 安装PyTorch (jetson版本)pip3 install torch torchvision --index-url https://download.pytorch.org/whl/torch-stable.html# 安装TensorRT-LLMgit clone https://github.com/NVIDIA/TensorRT-LLM.gitcd TensorRT-LLMgit checkout tags/v0.5.0 TensorRT-LLM核心概念1. 模型转换流程12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273&quot;&quot;&quot;TensorRT-LLM模型转换将HuggingFace模型转换为TensorRT格式&quot;&quot;&quot;import torchfrom tensorrt_llm.models import LLaMAForCausalLMfrom tensorrt_llm._utils import pad_vocab_sizefrom transformers import LlamaForCausalLM, LlamaTokenizerimport tensorrt as trtclass ModelConverter: &quot;&quot;&quot; 模型转换器 &quot;&quot;&quot; def __init__(self, model_path: str, output_dir: str): self.model_path = model_path self.output_dir = output_dir def convert_llama(self, model_size: int = 7): &quot;&quot;&quot; 转换LLaMA模型 &quot;&quot;&quot; print(f&quot;Loading LLaMA-&#123;model_size&#125;B from &#123;self.model_path&#125;&quot;) # 加载HuggingFace模型 hf_model = LlamaForCausalLM.from_pretrained( self.model_path, torch_dtype=torch.float16 ) tokenizer = LlamaTokenizer.from_pretrained(self.model_path) # 构建TensorRT-LLM模型 if model_size == 7: num_layers = 32 hidden_size = 4096 num_heads = 32 vocab_size = 32000 elif model_size == 13: num_layers = 40 hidden_size = 5120 num_heads = 40 vocab_size = 32000 # 创建模型配置 trt_llm = LLaMAForCausalLM( num_layers=num_layers, num_heads=num_heads, hidden_size=hidden_size, vocab_size=pad_vocab_size(vocab_size, 64), max_position_embeddings=4096 ) # 复制权重 trt_llm.load_from_hf_model(hf_model) # 保存 self.save_model(trt_llm, tokenizer) return trt_llm def save_model(self, model, tokenizer): &quot;&quot;&quot;保存转换后的模型&quot;&quot;&quot; import os os.makedirs(self.output_dir, exist_ok=True) # 保存模型 model.save(self.output_dir) # 保存tokenizer tokenizer.save_pretrained(self.output_dir) print(f&quot;Model saved to &#123;self.output_dir&#125;&quot;) 2. TensorRT引擎构建123456789101112131415161718192021222324#!/bin/bash# build_engine.sh# 构建TensorRT引擎MODEL_DIR=&quot;./models/llama-7b&quot;ENGINE_DIR=&quot;./engines/llama-7b&quot;TP_SIZE=1 # Tensor Parallel sizeMAX_BATCH_SIZE=8MAX_INPUT_LEN=4096MAX_OUTPUT_LEN=512python3 tensorrt_llm/examples/llama/build.py \ --model_dir $&#123;MODEL_DIR&#125; \ --tp_size $&#123;TP_SIZE&#125; \ --pp_size 1 \ --dtype float16 \ --max_batch_size $&#123;MAX_BATCH_SIZE&#125; \ --max_input_len $&#123;MAX_INPUT_LEN&#125; \ --max_output_len $&#123;MAX_OUTPUT_LEN&#125; \ --output_dir $&#123;ENGINE_DIR&#125; \ --use_gpt_attention_plugin \ --use_rms_norm_plugin \ --use_gemm_plugin \ --enable_context_fmha 3. Python推理接口12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182838485868788899091929394959697import tensorrt as trtimport tensorrt_llmfrom tensorrt_llm.runtime import ModelRunnerclass TensorRTLLMRunner: &quot;&quot;&quot; TensorRT-LLM运行时封装 &quot;&quot;&quot; def __init__(self, engine_dir: str, tokenizer_dir: str): self.runtime = trt.Runtime(trt.Logger(trt.WARNING)) # 加载引擎 with open(f&quot;&#123;engine_dir&#125;/rank0.engine&quot;, &quot;rb&quot;) as f: self.engine = self.runtime.deserialize_cuda_engine(f.read()) self.runner = ModelRunner.from_engine(self.engine) # 加载tokenizer from transformers import AutoTokenizer self.tokenizer = AutoTokenizer.from_pretrained(tokenizer_dir) def generate(self, prompt: str, max_new_tokens: int = 256, temperature: float = 0.7, top_p: float = 0.9): &quot;&quot;&quot; 生成文本 &quot;&quot;&quot; # Tokenize input_ids = self.tokenizer.encode(prompt, return_tensors=&quot;pt&quot;) input_len = input_ids.shape[1] # 准备batch batch_input_ids = input_ids.cuda() # 采样参数 sampling_config = &#123; &quot;temperature&quot;: temperature, &quot;top_p&quot;: top_p, &quot;max_new_tokens&quot;: max_new_tokens &#125; # 运行推理 outputs = self.runner.generate( batch_input_ids, max_new_tokens=max_new_tokens, temperature=temperature, top_p=top_p, stop_words_list=None, pad_id=0 ) # 解码 generated_text = self.tokenizer.decode( outputs[0][0][input_len:], skip_special_tokens=True ) return generated_text def batch_generate(self, prompts: list, max_new_tokens: int = 256): &quot;&quot;&quot; 批量生成 &quot;&quot;&quot; # Tokenize input_ids_list = [ self.tokenizer.encode(p, return_tensors=&quot;pt&quot;) for p in prompts ] # Padding max_len = max(ids.shape[1] for ids in input_ids_list) padded = [ torch.cat([ ids, torch.zeros(1, max_len - ids.shape[1], dtype=torch.long) ], dim=1).cuda() for ids in input_ids_list ] batch_input_ids = torch.cat(padded, dim=0) # 推理 outputs = self.runner.generate( batch_input_ids, max_new_tokens=max_new_tokens ) # 解码 results = [] for i, ids in enumerate(input_ids_list): input_len = ids.shape[1] text = self.tokenizer.decode( outputs[i][0][input_len:], skip_special_tokens=True ) results.append(text) return results Jetson部署实战1. 完整部署脚本#!/usr/bin/env python3&quot;&quot;&quot;Jetson部署脚本&quot;&quot;&quot;import torchimport gcimport timeimport argparsefrom pathlib import Pathclass JetsonDeployer: &quot;&quot;&quot; Jetson部署器 &quot;&quot;&quot; def __init__(self, model_path: str, quantize_mode: str = &quot;fp16&quot;): self.model_path = model_path self.quantize_mode = quantize_mode self.model = None # 检查GPU print(f&quot;CUDA available: &#123;torch.cuda.is_available()&#125;&quot;) if torch.cuda.is_available(): print(f&quot;GPU: &#123;torch.cuda.get_device_name()&#125;&quot;) print(f&quot;GPU Memory: &#123;torch.cuda.get_device_properties(0).total_memory / 1e9:.1f&#125; GB&quot;) def load_model(self): &quot;&quot;&quot;加载模型&quot;&quot;&quot; print(f&quot;Loading model from &#123;self.model_path&#125;&quot;) if &quot;llama&quot; in self.model_path.lower(): from transformers import LlamaForCausalLM, LlamaTokenizer self.model = LlamaForCausalLM.from_pretrained( self.model_path, torch_dtype=torch.float16, device_map=&quot;auto&quot; ) self.tokenizer = LlamaTokenizer.from_pretrained(self.model_path) elif &quot;chatglm&quot; in self.model_path.lower(): from transformers import AutoModel, AutoTokenizer self.model = AutoModel.from_pretrained( self.model_path, torch_dtype=torch.float16, trust_remote_code=True ).half().cuda() self.tokenizer = AutoTokenizer.from_pretrained( self.model_path, trust_remote_code=True ) gc.collect() torch.cuda.empty_cache() print(&quot;Model loaded successfully&quot;) def quantize_model(self, mode: str = &quot;int8&quot;): &quot;&quot;&quot;模型量化&quot;&quot;&quot; print(f&quot;Quantizing model to &#123;mode&#125;&quot;) if mode == &quot;int8&quot;: from transformers import BitsAndBytesConfig quant_config = BitsAndBytesConfig( load_in_8bit=True, llm_int8_threshold=6.0, llm_int8_has_fp16_weight=False ) # 重新加载量化模型 if &quot;llama&quot; in self.model_path.lower(): from transformers import LlamaForCausalLM self.model = LlamaForCausalLM.from_pretrained( self.model_path, quantization_config=quant_config, device_map=&quot;auto&quot; ) gc.collect() print(&quot;Quantization completed&quot;) def benchmark(self, prompt: str = &quot;介绍自己&quot;, num_runs: int = 10): &quot;&quot;&quot;性能测试&quot;&quot;&quot; print(&quot;
=== Benchmark ===&quot;) # Warm up _ = self.generate(prompt, max_new_tokens=32) # 计时 latencies = [] tokens_per_second = [] for i in range(num_runs): torch.cuda.synchronize() start = time.time() output = self.generate(prompt, max_new_tokens=128) torch.cuda.synchronize() end = time.time() latency = end - start tokens = len(self.tokenizer.encode(output)) tps = tokens / latency latencies.append(latency) tokens_per_second.append(tps) print(f&quot;Run &#123;i+1&#125;: &#123;latency:.2f&#125;s, &#123;tps:.2f&#125; tokens/s&quot;) print(f&quot;
=== Results ===&quot;) print(f&quot;Average latency: &#123;sum(latencies)/len(latencies):.2f&#125;s&quot;) print(f&quot;Average throughput: &#123;sum(tokens_per_second)/len(tokens_per_second):.2f&#125; tokens/s&quot;) def generate(self, prompt: str, max_new_tokens: int = 256): &quot;&quot;&quot;生成文本&quot;&quot;&quot; inputs = self.tokenizer(prompt, return_tensors=&quot;pt&quot;).to(&quot;cuda&quot;) with torch.no_grad(): outputs = self.model.generate( **inputs, max_new_tokens=max_new_tokens, do_sample=True, temperature=0.7, top_p=0.9 ) return self.tokenizer.decode(outputs[0], skip_special_tokens=True)if __name__ == &quot;__main__&quot;: parser = argparse.ArgumentParser() parser.add_argument(&quot;--model_path&quot;, type=str, required=True) parser.add_argument(&quot;--quantize&quot;, type=str, default=&quot;fp16&quot;, choices=[&quot;fp16&quot;, &quot;int8&quot;, &quot;int4&quot;]) parser.add_argument(&quot;--benchmark&quot;, action=&quot;store_true&quot;) parser.add_argument(&quot;--prompt&quot;, type=str, default=&quot;介绍人工智能的发展历史&quot;) args = parser.parse_args() # 部署 deployer = JetsonDeployer(args.model_path, args.quantize) deployer.load_model() if args.quantize != &quot;fp16&quot;: deployer.quantize_model(args.quantize) # 测试 output = deployer.generate(args.prompt) print(f&quot;
