&#123;output&#125;&quot;) if args.benchmark: deployer.benchmark(args.prompt) 2. TensorRT-LLM推理服务1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950from fastapi import FastAPI, HTTPExceptionfrom pydantic import BaseModelimport uvicornapp = FastAPI(title=&quot;LLM Inference API&quot;)class InferenceService: &quot;&quot;&quot; 推理服务 &quot;&quot;&quot; def __init__(self, engine_dir: str): self.runner = TensorRTLLMRunner(engine_dir, tokenizer_dir) def infer(self, prompt: str, **kwargs) -&gt; str: return self.runner.generate(prompt, **kwargs)class GenerateRequest(BaseModel): prompt: str max_tokens: int = 256 temperature: float = 0.7 top_p: float = 0.9@app.post(&quot;/generate&quot;)async def generate(request: GenerateRequest): &quot;&quot;&quot;生成接口&quot;&quot;&quot; try: result = inference_service.infer( request.prompt, max_new_tokens=request.max_tokens, temperature=request.temperature, top_p=request.top_p ) return &#123;&quot;generated_text&quot;: result&#125; except Exception as e: raise HTTPException(status_code=500, detail=str(e))@app.get(&quot;/health&quot;)async def health(): return &#123;&quot;status&quot;: &quot;ok&quot;&#125;# 启动if __name__ == &quot;__main__&quot;: import sys engine_dir = sys.argv[1] if len(sys.argv) &gt; 1 else &quot;./engines&quot; inference_service = InferenceService(engine_dir) uvicorn.run(app, host=&quot;0.0.0.0&quot;, port=8080) 性能优化技巧1. 内存优化123456789101112131415161718192021222324252627class MemoryOptimizer: &quot;&quot;&quot; 内存优化工具 &quot;&quot;&quot; @staticmethod def enable_gradient_checkpointing(model): &quot;&quot;&quot;梯度检查点，减少显存占用&quot;&quot;&quot; if hasattr(model, &#x27;gradient_checkpointing_enable&#x27;): model.gradient_checkpointing_enable() return model @staticmethod def clear_cache(): &quot;&quot;&quot;清理GPU缓存&quot;&quot;&quot; import torch gc.collect() torch.cuda.empty_cache() @staticmethod def print_memory_stats(): &quot;&quot;&quot;打印显存使用情况&quot;&quot;&quot; import torch if torch.cuda.is_available(): allocated = torch.cuda.memory_allocated() / 1e9 reserved = torch.cuda.memory_reserved() / 1e9 print(f&quot;Memory allocated: &#123;allocated:.2f&#125; GB&quot;) print(f&quot;Memory reserved: &#123;reserved:.2f&#125; GB&quot;) 2. 批处理优化12345678910111213141516171819202122232425262728293031323334353637383940class DynamicBatching: &quot;&quot;&quot; 动态批处理 合并多个请求提高吞吐量 &quot;&quot;&quot; def __init__(self, runner, max_batch_size=8, max_wait_ms=100): self.runner = runner self.max_batch_size = max_batch_size self.max_wait_ms = max_wait_ms self.pending_requests = [] async def add_request(self, prompt: str): &quot;&quot;&quot;添加请求&quot;&quot;&quot; future = asyncio.Future() self.pending_requests.append((prompt, future)) # 检查是否需要处理 if len(self.pending_requests) &gt;= self.max_batch_size: await self.process_batch() return await future async def process_batch(self): &quot;&quot;&quot;处理批次&quot;&quot;&quot; if not self.pending_requests: return # 取出请求 batch_size = min(len(self.pending_requests), self.max_batch_size) batch = self.pending_requests[:batch_size] self.pending_requests = self.pending_requests[batch_size:] prompts = [p for p, _ in batch] # 批量推理 outputs = self.runner.batch_generate(prompts) # 设置结果 for (_, future), output in zip(batch, outputs): future.set_result(output) 总结在Jetson嵌入式平台上部署大模型需要综合考虑模型大小、推理速度和内存限制。通过TensorRT-LLM优化、模型量化和批处理等技术，可以在边缘设备上实现大模型的高效推理。本文介绍了完整的部署流程和优化技巧，为开发者提供了实用的参考方案。 参考资源 TensorRT-LLM GitHub Jetson官方文档 Deep Learning Inference

引言LangChain是构建LLM应用的主流框架，提供了丰富的组件和工具链。本文将深入探讨如何使用LangChain构建生产级别的RAG应用，包括文档处理、检索优化、结果重排序等高级特性。 LangChain核心组件1. 文档加载与分割123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475from langchain.document_loaders import ( PyPDFLoader, UnstructuredHTMLLoader, CSVLoader, JSONLoader, Docx2txtLoader)from langchain.text_splitter import ( RecursiveCharacterTextSplitter, MarkdownTextSplitter, PythonCodeTextSplitter)from langchain.schema import Documentclass DocumentPipeline: &quot;&quot;&quot; 文档处理流水线 &quot;&quot;&quot; def __init__(self, chunk_size=500, chunk_overlap=50): self.chunk_size = chunk_size self.chunk_overlap = chunk_overlap self.text_splitters = &#123; &quot;recursive&quot;: RecursiveCharacterTextSplitter( chunk_size=chunk_size, chunk_overlap=chunk_overlap, length_function=len, separators=[&quot;

&quot;, &quot;
&quot;, &quot;。&quot;, &quot;！&quot;, &quot;？&quot;, &quot; &quot;, &quot;&quot;] ), &quot;markdown&quot;: MarkdownTextSplitter( chunk_size=chunk_size, chunk_overlap=chunk_overlap ), &quot;code&quot;: PythonCodeTextSplitter( chunk_size=chunk_size, chunk_overlap=chunk_overlap ) &#125; def load_pdf(self, file_path: str) -&gt; list[Document]: &quot;&quot;&quot;加载PDF&quot;&quot;&quot; loader = PyPDFLoader(file_path) pages = loader.load_and_split() return pages def load_html(self, file_path: str) -&gt; list[Document]: &quot;&quot;&quot;加载HTML&quot;&quot;&quot; loader = UnstructuredHTMLLoader(file_path) docs = loader.load() return docs def load_docx(self, file_path: str) -&gt; list[Document]: &quot;&quot;&quot;加载Word文档&quot;&quot;&quot; loader = Docx2txtLoader(file_path) docs = loader.load() return docs def load_json(self, file_path: str, jq_schema: str = &quot;.[]&quot;) -&gt; list[Document]: &quot;&quot;&quot;加载JSON&quot;&quot;&quot; loader = JSONLoader(file_path, jq_schema=jq_schema) docs = loader.load() return docs def split_documents(self, documents: list[Document], splitter_type: str = &quot;recursive&quot;) -&gt; list[Document]: &quot;&quot;&quot; 分割文档 &quot;&quot;&quot; splitter = self.text_splitters.get(splitter_type, self.text_splitters[&quot;recursive&quot;]) return splitter.split_documents(documents) def process_url(self, url: str) -&gt; list[Document]: &quot;&quot;&quot;从URL加载内容&quot;&quot;&quot; from langchain.document_loaders import WebBaseLoader loader = WebBaseLoader(url) docs = loader.load() return self.split_documents(docs) 2. Embedding与向量化1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556from langchain.embeddings import OpenAIEmbeddings, HuggingFaceEmbeddingsfrom langchain.vectorstores import Chroma, FAISS, Milvusfrom langchain.embeddings import CacheBackedEmbeddingsfrom transformers import AutoTokenizer, AutoModelimport torchclass EmbeddingManager: &quot;&quot;&quot; Embedding管理器 &quot;&quot;&quot; def __init__(self, provider: str = &quot;openai&quot;): self.provider = provider self.embeddings = self._init_embeddings() def _init_embeddings(self): if self.provider == &quot;openai&quot;: return OpenAIEmbeddings( model=&quot;text-embedding-ada-002&quot;, openai_api_key=&quot;your-api-key&quot; ) elif self.provider == &quot;huggingface&quot;: return HuggingFaceEmbeddings( model_name=&quot;sentence-transformers/all-MiniLM-L6-v2&quot;, model_kwargs=&#123;&#x27;device&#x27;: &#x27;cuda&#x27;&#125;, encode_kwargs=&#123;&#x27;normalize_embeddings&#x27;: True&#125; ) elif self.provider == &quot;m3e&quot;: return HuggingFaceEmbeddings( model_name=&quot;moka-ai/m3e-base&quot;, model_kwargs=&#123;&#x27;device&#x27;: &#x27;cuda&#x27;&#125;, encode_kwargs=&#123;&#x27;normalize_embeddings&#x27;: True&#125; ) def create_vectorstore(self, documents: list[Document], db_type: str = &quot;chroma&quot;, persist_directory: str = None) -&gt; any: &quot;&quot;&quot; 创建向量数据库 &quot;&quot;&quot; if db_type == &quot;chroma&quot;: return Chroma.from_documents( documents=documents, embedding=self.embeddings, persist_directory=persist_directory ) elif db_type == &quot;faiss&quot;: return FAISS.from_documents( documents=documents, embedding=self.embeddings ) elif db_type == &quot;milvus&quot;: return Milvus.from_documents( documents=documents, embedding=self.embeddings, connection_args=&#123;&quot;host&quot;: &quot;localhost&quot;, &quot;port&quot;: &quot;19530&quot;&#125; ) 高级RAG模式1. 父子文档检索12345678910111213141516171819202122232425262728293031323334from langchain.retrievers import ParentDocumentRetrieverfrom langchain.storage import InMemoryStoreclass ParentDocumentSearch: &quot;&quot;&quot; 父子文档检索器 父文档提供完整上下文，子文档用于精确匹配 &quot;&quot;&quot; def __init__(self, vectorstore, embeddings): # 存储父文档 self.store = InMemoryStore() self.retriever = ParentDocumentRetriever( vectorstore=vectorstore, docstore=self.store, child_splitter=RecursiveCharacterTextSplitter( chunk_size=400, chunk_overlap=40 ), parent_splitter=RecursiveCharacterTextSplitter( chunk_size=2000, chunk_overlap=200 ), child_metadata=&#123;&quot;source&quot;: &quot;child&quot;&#125;, parent_metadata=&#123;&quot;source&quot;: &quot;parent&quot;&#125; ) def add_documents(self, documents: list[Document]): &quot;&quot;&quot;添加文档&quot;&quot;&quot; self.retriever.add_documents(documents) def get_relevant_documents(self, query: str) -&gt; list[Document]: &quot;&quot;&quot;获取相关文档&quot;&quot;&quot; return self.retriever.get_relevant_documents(query) 2. 自查询检索器12345678910111213141516171819202122232425262728293031323334353637383940from langchain.retrievers import SelfQueryRetrieverfrom langchain.chains.query_constructor.base import AttributeInfoclass SelfQuerySearch: &quot;&quot;&quot; 自查询检索器 自动从自然语言中提取过滤条件 &quot;&quot;&quot; def __init__(self, vectorstore, llm, document_contents: str, metadata_field_info: list): self.metadata_field_info = [ AttributeInfo( name=&quot;source&quot;, description=&quot;The source of the document&quot;, type=&quot;string&quot; ), AttributeInfo( name=&quot;date&quot;, description=&quot;The date of the document&quot;, type=&quot;datetime&quot; ), AttributeInfo( name=&quot;category&quot;, description=&quot;The category of the document&quot;, type=&quot;string&quot; ) ] self.retriever = SelfQueryRetriever.from_llm( llm=llm, vectorstore=vectorstore, document_contents=document_contents, metadata_field_info=self.metadata_field_info ) def search(self, query: str) -&gt; list[Document]: &quot;&quot;&quot; 支持自然语言过滤的检索 例如: &quot;查找2023年3月关于AI的技术文档&quot; &quot;&quot;&quot; return self.retriever.get_relevant_documents(query) 3. 集成检索器12345678910111213141516171819202122from langchain.retrievers import EnsembleRetrieverclass EnsembleSearch: &quot;&quot;&quot; 集成检索器 结合多种检索方法 &quot;&quot;&quot; def __init__(self, vectorstore, bm25_retriever, keyword_weights: list = None): # 向量检索 vector_retriever = vectorstore.as_retriever( search_kwargs=&#123;&quot;k&quot;: 10&#125; ) # BM25检索 self.retriever = EnsembleRetriever( retrievers=[vector_retriever, bm25_retriever], weights=keyword_weights or [0.5, 0.5] # 默认各50% ) def search(self, query: str) -&gt; list[Document]: &quot;&quot;&quot;集成检索&quot;&quot;&quot; return self.retriever.get_relevant_documents(query) 4. 上下文压缩检索12345678910111213141516171819202122from langchain.retrievers import ContextualCompressionRetrieverfrom langchain.retrievers.document_compressors import LLMChainExtractor, LLMChainFilterclass ContextualCompressionSearch: &quot;&quot;&quot; 上下文压缩检索 压缩检索结果，提取最相关的部分 &quot;&quot;&quot; def __init__(self, base_retriever, llm): # 使用LLM提取相关内容 compressor = LLMChainExtractor.from_llm(llm) self.retriever = ContextualCompressionRetriever( base_compressor=compressor, base_retriever=base_retriever ) def search(self, query: str) -&gt; list[Document]: &quot;&quot;&quot; 返回压缩后的相关文档 &quot;&quot;&quot; return self.retriever.get_relevant_documents(query) Chain构建1. 基础QA Chain12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455from langchain.chains import RetrievalQAfrom langchain.prompts import PromptTemplatefrom langchain.chat_models import ChatOpenAIclass QABot: &quot;&quot;&quot; 问答机器人 &quot;&quot;&quot; def __init__(self, vectorstore, llm_model=&quot;gpt-3.5-turbo&quot;): self.llm = ChatOpenAI(model=llm_model, temperature=0) self.vectorstore = vectorstore def build_chain(self, prompt_template: str = None): &quot;&quot;&quot; 构建问答链 &quot;&quot;&quot; if prompt_template is None: prompt_template = &quot;&quot;&quot;使用以下背景信息回答问题。如果你不知道答案，请明确说明，不要编造答案。背景信息：&#123;context&#125;问题：&#123;question&#125;回答：&quot;&quot;&quot; PROMPT = PromptTemplate( template=prompt_template, input_variables=[&quot;context&quot;, &quot;question&quot;] ) return RetrievalQA.from_chain_type( llm=self.llm, chain_type=&quot;stuff&quot;, retriever=self.vectorstore.as_retriever( search_kwargs=&#123;&quot;k&quot;: 5&#125; ), chain_type_kwargs=&#123; &quot;prompt&quot;: PROMPT, &quot;document_variable_name&quot;: &quot;context&quot; &#125;, return_source_documents=True ) def ask(self, question: str) -&gt; dict: &quot;&quot;&quot; 提问 &quot;&quot;&quot; chain = self.build_chain() result = chain(&#123;&quot;query&quot;: question&#125;) return &#123; &quot;answer&quot;: result[&quot;result&quot;], &quot;sources&quot;: result.get(&quot;source_documents&quot;, []) &#125; 2. 对话检索链1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677from langchain.chains import ConversationalRetrievalChainfrom langchain.memory import ConversationBufferMemoryclass ConversationalBot: &quot;&quot;&quot; 对话式问答机器人 支持多轮对话 &quot;&quot;&quot; def __init__(self, vectorstore, llm_model=&quot;gpt-3.5-turbo&quot;): self.llm = ChatOpenAI(model=llm_model, temperature=0) self.vectorstore = vectorstore self.memory = ConversationBufferMemory( memory_key=&quot;chat_history&quot;, return_messages=True, output_key=&quot;answer&quot; ) def build_chain(self): &quot;&quot;&quot; 构建对话链 &quot;&quot;&quot; return ConversationalRetrievalChain.from_llm( llm=self.llm, retriever=self.vectorstore.as_retriever( search_kwargs=&#123;&quot;k&quot;: 5&#125; ), memory=self.memory, condense_question_prompt=self._get_condense_prompt(), combine_docs_chain_kwargs=&#123;&quot;prompt&quot;: self._get_doc_prompt()&#125; ) def _get_condense_prompt(self): &quot;&quot;&quot; 问题改写prompt 将对话历史+新问题改写为独立问题 &quot;&quot;&quot; template = &quot;&quot;&quot;给定以下对话历史和一个后续问题，将后续问题重新表述为一个独立的问题。对话历史：&#123;chat_history&#125;后续问题：&#123;question&#125;独立问题：&quot;&quot;&quot; return PromptTemplate( template=template, input_variables=[&quot;chat_history&quot;, &quot;question&quot;] ) def _get_doc_prompt(self): &quot;&quot;&quot; 文档问答prompt &quot;&quot;&quot; template = &quot;&quot;&quot;使用以下文档回答问题。文档：&#123;context&#125;问题：&#123;question&#125;回答：&quot;&quot;&quot; return PromptTemplate( template=template, input_variables=[&quot;context&quot;, &quot;question&quot;] ) def chat(self, question: str) -&gt; dict: &quot;&quot;&quot; 对话 &quot;&quot;&quot; chain = self.build_chain() result = chain(&#123;&quot;question&quot;: question&#125;) return &#123; &quot;answer&quot;: result[&quot;answer&quot;], &quot;chat_history&quot;: result.get(&quot;chat_history&quot;, []) &#125; 3. 带来源引用的RAG1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950class SourceCitationChain: &quot;&quot;&quot; 带来源引用的RAG链 &quot;&quot;&quot; def __init__(self, vectorstore, llm): self.vectorstore = vectorstore self.llm = llm def build_chain(self): &quot;&quot;&quot; 构建带引用的chain &quot;&quot;&quot; from langchain.chains import LLMChain from langchain.prompts import PromptTemplate # 检索+生成链 prompt = PromptTemplate( template=&quot;&quot;&quot;根据以下文档回答问题，并在回答中引用文档来源。文档：&#123;context&#125;问题：&#123;question&#125;请在回答中用[1]、[2]等形式标注引用来源。回答：&quot;&quot;&quot;, input_variables=[&quot;context&quot;, &quot;question&quot;] ) llm_chain = LLMChain(llm=self.llm, prompt=prompt) from langchain.chains import RetrievalQAWithSourcesChain return RetrievalQAWithSourcesChain( combine_documents_chain=llm_chain, retriever=self.vectorstore.as_retriever() ) def ask_with_sources(self, question: str) -&gt; dict: &quot;&quot;&quot; 提问并返回来源 &quot;&quot;&quot; chain = self.build_chain() result = chain(&#123;&quot;question&quot;: question&#125;) return &#123; &quot;answer&quot;: result[&quot;answer&quot;], &quot;sources&quot;: result.get(&quot;sources&quot;, &quot;&quot;), &quot;source_documents&quot;: result.get(&quot;source_documents&quot;, []) &#125; 生产级部署1. 完整RAG服务123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111from fastapi import FastAPI, HTTPExceptionfrom pydantic import BaseModelfrom typing import List, Optionalimport uvicornapp = FastAPI(title=&quot;RAG API&quot;, version=&quot;1.0&quot;)class RAGService: &quot;&quot;&quot; RAG服务 &quot;&quot;&quot; def __init__(self, model_path: str, vectorstore_path: str): from langchain.vectorstores import Chroma from langchain.embeddings import HuggingFaceEmbeddings # 加载向量数据库 embeddings = HuggingFaceEmbeddings( model_name=&quot;moka-ai/m3e-base&quot; ) self.vectorstore = Chroma( persist_directory=vectorstore_path, embedding_function=embeddings ) # 初始化LLM self.llm = ChatOpenAI(model=&quot;gpt-3.5-turbo&quot;) # 构建chain self.qa_chain = self._build_qa_chain() def _build_qa_chain(self): from langchain.chains import RetrievalQA return RetrievalQA.from_llm( llm=self.llm, retriever=self.vectorstore.as_retriever( search_kwargs=&#123;&quot;k&quot;: 5&#125; ) ) def query(self, question: str) -&gt; dict: &quot;&quot;&quot;查询&quot;&quot;&quot; result = self.qa_chain(&#123;&quot;query&quot;: question&#125;) return &#123; &quot;answer&quot;: result[&quot;result&quot;], &quot;sources&quot;: result.get(&quot;source_documents&quot;, []) &#125; def add_documents(self, documents: List[str], metadatas: List[dict]): &quot;&quot;&quot;添加文档&quot;&quot;&quot; from langchain.schema import Document docs = [ Document(page_content=doc, metadata=meta) for doc, meta in zip(documents, metadatas) ] self.vectorstore.add_documents(docs)# API端点class QueryRequest(BaseModel): question: str use_citation: bool = Falseclass QueryResponse(BaseModel): answer: str sources: List[dict]# 全局RAG服务实例rag_service = None@app.on_event(&quot;startup&quot;)async def startup(): global rag_service rag_service = RAGService( model_path=&quot;gpt-3.5-turbo&quot;, vectorstore_path=&quot;./vectorstore&quot; )@app.post(&quot;/query&quot;, response_model=QueryResponse)async def query(request: QueryRequest): &quot;&quot;&quot;查询接口&quot;&quot;&quot; if rag_service is None: raise HTTPException(status_code=500, detail=&quot;Service not initialized&quot;) result = rag_service.query(request.question) return QueryResponse( answer=result[&quot;answer&quot;], sources=[ &#123; &quot;content&quot;: doc.page_content[:200], &quot;metadata&quot;: doc.metadata &#125; for doc in result.get(&quot;sources&quot;, []) ] )@app.post(&quot;/documents&quot;)async def add_documents(documents: List[str], metadatas: List[dict]): &quot;&quot;&quot;添加文档&quot;&quot;&quot; if rag_service is None: raise HTTPException(status_code=500, detail=&quot;Service not initialized&quot;) rag_service.add_documents(documents, metadatas) return &#123;&quot;status&quot;: &quot;success&quot;, &quot;count&quot;: len(documents)&#125;if __name__ == &quot;__main__&quot;: uvicorn.run(app, host=&quot;0.0.0.0&quot;, port=8000) 性能优化1. 缓存Embedding12345678910111213141516171819202122232425from langchain.embeddings import CacheBackedEmbeddingsfrom langchain.storage import LocalFileStorefrom functools import partialclass CachedEmbedding: &quot;&quot;&quot; 带缓存的Embedding 避免重复计算 &quot;&quot;&quot; def __init__(self, underlying_embeddings): # 本地文件系统缓存 store = LocalFileStore(&quot;./cache/embeddings&quot;) self.embeddings = CacheBackedEmbeddings( underlying_embeddings=underlying_embeddings, document_embedding_cache=store ) def embed_documents(self, texts: List[str]) -&gt; List[List[float]]: &quot;&quot;&quot;缓存的文档嵌入&quot;&quot;&quot; return self.embeddings.embed_documents(texts) def embed_query(self, query: str) -&gt; List[float]: &quot;&quot;&quot;缓存的查询嵌入&quot;&quot;&quot; return self.embeddings.embed_query(query) 2. 批量处理1234567891011121314151617181920212223242526class BatchProcessor: &quot;&quot;&quot; 批量文档处理 &quot;&quot;&quot; def __init__(self, embedding_manager, vectorstore): self.embedding_manager = embedding_manager self.vectorstore = vectorstore def process_large_dataset(self, documents: List[Document], batch_size: int = 100): &quot;&quot;&quot; 分批处理大量文档 &quot;&quot;&quot; for i in range(0, len(documents), batch_size): batch = documents[i:i + batch_size] print(f&quot;Processing batch &#123;i // batch_size + 1&#125;&quot;) # 添加到向量数据库 self.vectorstore.add_documents(batch) def incremental_indexing(self, new_documents: List[Document]): &quot;&quot;&quot; 增量索引 &quot;&quot;&quot; # 只索引新文档 self.vectorstore.add_documents(new_documents) 总结LangChain为构建RAG应用提供了完整的基础设施。通过合理使用文档加载器、分割器、检索器和Chain组件，可以构建功能强大的企业级问答系统。本文介绍的高级特性如父子文档检索、自查询检索、上下文压缩等，可以进一步提升系统的准确性和用户体验。在实际生产环境中，还需要考虑性能优化、监控告警、多租户隔离等问题，以确保系统的稳定运行。 参考资源 LangChain官方文档 RAG教程 LangChain Hub

引言2023年，阿里云发布了通义千问（Qwen）系列大模型，这是国内科技巨头在开源大模型领域的重要布局。Qwen凭借出色的中文能力和开放的生态，迅速成为开源社区的热门选择。本文将深入分析Qwen的技术架构、训练方法和应用实践。 Qwen技术架构1. 模型架构设计Qwen采用了类似LLaMA的Transformer解码器架构，并进行了多项技术优化： 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182838485868788899091929394959697import torchimport torch.nn as nnimport mathclass QwenAttention(nn.Module): &quot;&quot;&quot; Qwen注意力机制 支持Flash Attention优化 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.hidden_size = config.hidden_size self.num_heads = config.num_attention_heads self.head_dim = self.hidden_size // self.num_heads self.max_position_embeddings = config.max_position_embeddings # 旋转位置编码（RoPE） self.rotary_emb = QwenRotaryEmbedding( dim=self.head_dim, max_position_embeddings=self.max_position_embeddings ) # QKV投影 self.qkv_proj = nn.Linear( self.hidden_size, 3 * self.hidden_size, bias=False ) self.o_proj = nn.Linear(self.hidden_size, self.hidden_size, bias=False) def forward(self, x, attention_mask=None, position_ids=None): B, T, C = x.shape # QKV投影 qkv = self.qkv_proj(x) qkv = qkv.reshape(B, T, 3, self.num_heads, self.head_dim) qkv = qkv.permute(2, 0, 3, 1, 4) # [3, B, H, T, D] q, k, v = qkv[0], qkv[1], qkv[2] # 应用旋转位置编码 q, k = self.rotary_emb(q, k, position_ids) # Flash Attention if hasattr(torch.nn.functional, &#x27;scaled_dot_product_attention&#x27;): attn_output = torch.nn.functional.scaled_dot_product_attention( q, k, v, attn_mask=attention_mask, dropout_p=0.0 if not self.training else 0.1 ) else: # 兼容实现 attn_output = self._fallback_attention(q, k, v, attention_mask) return self.o_proj(attn_output) def _fallback_attention(self, q, k, v, mask): scale = 1.0 / math.sqrt(self.head_dim) attn = torch.matmul(q, k.transpose(-2, -1)) * scale if mask is not None: attn = attn + mask attn = nn.functional.softmax(attn, dim=-1) return torch.matmul(attn, v)class QwenRotaryEmbedding(nn.Module): &quot;&quot;&quot; Qwen旋转位置编码 &quot;&quot;&quot; def __init__(self, dim, max_position_embeddings=2048, base=10000): super().__init__() inv_freq = 1.0 / (base ** (torch.arange(0, dim, 2).float() / dim)) self.register_buffer(&quot;inv_freq&quot;, inv_freq) def forward(self, q, k, position_ids=None): if position_ids is None: T = q.shape[2] position_ids = torch.arange(T, device=q.device).unsqueeze(0) # 计算频率 position_ids = position_ids.float() freqs = torch.einsum(&quot;i,j-&gt;ij&quot;, position_ids[0], self.inv_freq) emb = torch.cat((freqs, freqs), dim=-1) # 计算cos和sin cos = emb.cos() sin = emb.sin() # 旋转Q和K q_embed = self._rotate_half(q, cos, sin) k_embed = self._rotate_half(k, cos, sin) return q_embed, k_embed def _rotate_half(self, x, cos, sin): x1, x2 = x[..., :x.shape[-1]//2], x[..., x.shape[-1]//2:] return torch.cat((-x2, x1), dim=-1) * cos + x1 * (-sin) + x2 * cos 2. SwiGLU激活与门控12345678910111213141516171819class QwenMLP(nn.Module): &quot;&quot;&quot; Qwen前馈网络 使用SwiGLU激活函数 &quot;&quot;&quot; def __init__(self, config): super().__init__() hidden_size = config.hidden_size intermediate_size = config.intermediate_size self.gate_proj = nn.Linear(hidden_size, intermediate_size * 2, bias=False) self.up_proj = nn.Linear(hidden_size, intermediate_size, bias=False) self.down_proj = nn.Linear(intermediate_size, hidden_size, bias=False) def forward(self, x): gate = self.gate_proj(x) gate_1, gate_2 = gate.chunk(2, dim=-1) return self.down_proj(nn.functional.silu(gate_1) * self.up_proj(x)) 3. QwenBlock实现12345678910111213141516171819202122232425262728293031class QwenBlock(nn.Module): &quot;&quot;&quot; Qwen Transformer Block &quot;&quot;&quot; def __init__(self, config): super().__init__() self.attention = QwenAttention(config) self.mlp = QwenMLP(config) self.post_attention_layernorm = nn.RMSNorm( config.hidden_size, eps=config.layer_norm_epsilon ) self.input_layernorm = nn.RMSNorm( config.hidden_size, eps=config.layer_norm_epsilon ) def forward(self, x, attention_mask=None, position_ids=None): # 自注意力 + 残差连接 residual = x x = self.input_layernorm(x) x = self.attention(x, attention_mask, position_ids) x = residual + x # 前馈网络 + 残差连接 residual = x x = self.post_attention_layernorm(x) x = residual + self.mlp(x) return x Qwen模型系列 模型 参数量 上下文 特点 Qwen-1.8B 1.8B 2K 轻量级部署 Qwen-7B 7B 2K&#x2F;8K 主流版本 Qwen-14B 14B 2K&#x2F;8K 高性能 Qwen-72B 72B 2K&#x2F;8K 旗舰版本 Qwen-Chat - 2K 对话优化 Qwen训练技术1. 预训练数据处理123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475class QwenDataProcessor: &quot;&quot;&quot; Qwen预训练数据处理 &quot;&quot;&quot; def __init__(self, vocab_file): from transformers import AutoTokenizer self.tokenizer = AutoTokenizer.from_pretrained( vocab_file, trust_remote_code=True ) def prepare_training_data(self, text_files: List[str]) -&gt; Dataset: &quot;&quot;&quot; 准备预训练数据 &quot;&quot;&quot; all_texts = [] for file_path in text_files: with open(file_path, &#x27;r&#x27;, encoding=&#x27;utf-8&#x27;) as f: texts = f.readlines() # Tokenize for text in texts: if len(text.strip()) &lt; 10: continue tokens = self.tokenizer( text, max_length=2048, truncation=True, padding=&#x27;max_length&#x27; ) all_texts.append(&#123; &#x27;input_ids&#x27;: tokens[&#x27;input_ids&#x27;], &#x27;attention_mask&#x27;: tokens[&#x27;attention_mask&#x27;] &#125;) return Dataset.from_list(all_texts) def prepare_sft_data(self, conversations: List[dict]) -&gt; Dataset: &quot;&quot;&quot; 准备SFT数据 &quot;&quot;&quot; processed = [] for conv in conversations: prompt = self._format_conversation(conv) tokens = self.tokenizer( prompt, max_length=2048, truncation=True ) processed.append(&#123; &#x27;input_ids&#x27;: tokens[&#x27;input_ids&#x27;], &#x27;labels&#x27;: tokens[&#x27;input_ids&#x27;].copy() &#125;) return Dataset.from_list(processed) def _format_conversation(self, conv: dict) -&gt; str: &quot;&quot;&quot; 格式化对话 &quot;&quot;&quot; lines = [] for msg in conv[&#x27;messages&#x27;]: if msg[&#x27;role&#x27;] == &#x27;system&#x27;: lines.append(f&quot;System: &#123;msg[&#x27;content&#x27;]&#125;&quot;) elif msg[&#x27;role&#x27;] == &#x27;user&#x27;: lines.append(f&quot;User: &#123;msg[&#x27;content&#x27;]&#125;&quot;) elif msg[&#x27;role&#x27;] == &#x27;assistant&#x27;: lines.append(f&quot;Assistant: &#123;msg[&#x27;content&#x27;]&#125;&quot;) return &quot;
&quot;.join(lines) 2. RLHF训练流程1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253class QwenRLHFTrainer: &quot;&quot;&quot; Qwen RLHF训练 &quot;&quot;&quot; def __init__(self, model, ref_model, reward_model): self.model = model self.ref_model = ref_model self.reward_model = reward_model def compute_reward(self, response_ids, prompt_ids): &quot;&quot;&quot; 计算reward &quot;&quot;&quot; with torch.no_grad(): reward = self.reward_model( torch.cat([prompt_ids, response_ids], dim=1) ) return reward def compute_kl_divergence(self, response_ids, prompt_ids, gamma=0.1): &quot;&quot;&quot; 计算KL散度 &quot;&quot;&quot; with torch.no_grad(): ref_log_probs = self.ref_model( torch.cat([prompt_ids, response_ids], dim=1) ).log_probs ref_log_probs = ref_log_probs[:, prompt_ids.shape[1]:] new_log_probs = self.model( torch.cat([prompt_ids, response_ids], dim=1) ).log_probs[:, prompt_ids.shape[1]:] return (new_log_probs - ref_log_probs).mean() * gamma def ppo_update(self, batch): &quot;&quot;&quot; PPO更新 &quot;&quot;&quot; prompt_ids = batch[&#x27;prompt_ids&#x27;] response_ids = batch[&#x27;response_ids&#x27;] # 计算reward reward = self.compute_reward(response_ids, prompt_ids) # 计算KL散度 kl = self.compute_kl_divergence(response_ids, prompt_ids) # 组合损失 loss = -reward + kl # 反向传播 loss.backward() Qwen部署实践1. Transformers部署12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061from transformers import AutoModelForCausalLM, AutoTokenizerimport torchclass QwenDeployer: def __init__(self, model_path, device=&quot;cuda&quot;): self.tokenizer = AutoTokenizer.from_pretrained( model_path, trust_remote_code=True ) self.model = AutoModelForCausalLM.from_pretrained( model_path, trust_remote_code=True, torch_dtype=torch.float16, device_map=&quot;auto&quot; ) def chat(self, query, history=None, max_length=2048): &quot;&quot;&quot; 对话接口 &quot;&quot;&quot; if history is None: history = [] # 构建输入 prompt = self._build_prompt(query, history) inputs = self.tokenizer(prompt, return_tensors=&quot;pt&quot;).to(self.model.device) # 生成 with torch.no_grad(): outputs = self.model.generate( **inputs, max_new_tokens=max_length, do_sample=True, temperature=0.7, top_p=0.9, repetition_penalty=1.1 ) response = self.tokenizer.decode( outputs[0][inputs[&#x27;input_ids&#x27;].shape[1]:], skip_special_tokens=True ) return response.strip() def _build_prompt(self, query, history): &quot;&quot;&quot; 构建prompt &quot;&quot;&quot; prompt = &quot;&quot; for q, a in history: prompt += f&quot;User: &#123;q&#125;
Assistant: &#123;a&#125;
&quot; prompt += f&quot;User: &#123;query&#125;
Assistant: &quot; return prompt def batch_chat(self, queries): &quot;&quot;&quot; 批量对话 &quot;&quot;&quot; return [self.chat(q) for q in queries] 2. vLLM高性能部署123456789101112131415161718192021222324252627282930313233343536373839# vLLM部署脚本&quot;&quot;&quot;使用vLLM进行Qwen高性能推理安装：pip install vllm&quot;&quot;&quot;from vllm import LLM, SamplingParamsclass QwenvLLMDeployer: def __init__(self, model_path, tensor_parallel_size=1): self.llm = LLM( model=model_path, trust_remote_code=True, tensor_parallel_size=tensor_parallel_size, dtype=&#x27;float16&#x27; ) def generate(self, prompts, max_tokens=256, temperature=0.7): &quot;&quot;&quot; 高性能生成 &quot;&quot;&quot; sampling_params = SamplingParams( temperature=temperature, top_p=0.95, max_tokens=max_tokens ) outputs = self.llm.generate(prompts, sampling_params) return [output.outputs[0].text for output in outputs] def chat(self, query, history=None): &quot;&quot;&quot; 对话接口 &quot;&quot;&quot; prompt = self._build_prompt(query, history) outputs = self.generate([prompt]) return outputs[0].strip() 3. OpenAI兼容API12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849from fastapi import FastAPI, HTTPExceptionfrom pydantic import BaseModelimport uvicornapp = FastAPI(title=&quot;Qwen API&quot;)class ChatRequest(BaseModel): messages: list temperature: float = 0.7 max_tokens: int = 2048@app.post(&quot;/v1/chat/completions&quot;)async def chat_completions(request: ChatRequest): # 构建对话 history = [] for msg in request.messages: if msg[&#x27;role&#x27;] == &#x27;user&#x27;: history.append((msg[&#x27;content&#x27;], None)) elif msg[&#x27;role&#x27;] == &#x27;assistant&#x27;: if history: history[-1] = (history[-1][0], msg[&#x27;content&#x27;]) # 获取最后一条用户消息 query = request.messages[-1][&#x27;content&#x27;] # 生成回复 response = qwen_deployer.chat(query, [ (q, a) for q, a in history if a is not None ]) return &#123; &quot;id&quot;: &quot;chatcmpl-&quot; + generate_id(), &quot;choices&quot;: [&#123; &quot;index&quot;: 0, &quot;message&quot;: &#123; &quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: response &#125;, &quot;finish_reason&quot;: &quot;stop&quot; &#125;], &quot;usage&quot;: &#123; &quot;prompt_tokens&quot;: len(query) // 4, &quot;completion_tokens&quot;: len(response) // 4, &quot;total_tokens&quot;: (len(query) + len(response)) // 4 &#125; &#125;if __name__ == &quot;__main__&quot;: uvicorn.run(app, host=&quot;0.0.0.0&quot;, port=8000) Qwen生态工具1. LangChain集成12345678910111213141516171819202122232425262728from langchain.llms import OpenAIfrom langchain.chains import LLMChainclass QwenLangChain: &quot;&quot;&quot; LangChain集成 &quot;&quot;&quot; def __init__(self, model_path): # 使用HuggingFace LangChain后端 from langchain.llms import HuggingFacePipeline self.llm = HuggingFacePipeline.from_model_id( model_id=model_path, task=&quot;text-generation&quot;, model_kwargs=&#123; &quot;temperature&quot;: 0.7, &quot;max_length&quot;: 2048 &#125; ) def create_chain(self, prompt_template): &quot;&quot;&quot; 创建LLM Chain &quot;&quot;&quot; return LLMChain( llm=self.llm, prompt=prompt_template ) 总结Qwen作为阿里云在开源大模型领域的重要布局，凭借出色的中文能力和开放的生态，为开发者和企业提供了强大的AI能力。通过持续的技术创新和生态建设，Qwen正在成为国内最具影响力的开源大模型之一。未来，Qwen将继续在多模态、长上下文等方向发力，为用户带来更强大的AI体验。 参考资源 通义千问官网 Qwen GitHub Hugging Face Qwen

引言2023年，AI Agent（人工智能代理）成为大模型应用领域最热门的话题之一。AutoGPT、BabyAGI等项目的爆火，展示了自主代理在自动化任务执行方面的巨大潜力。本文将深入分析AI Agent的技术原理、架构设计以及实际应用场景。 AI Agent核心概念1. 什么是AI AgentAI Agent是一种能够自主感知环境、做出决策并执行动作的智能系统。与传统AI助手不同，Agent具有： 自主规划能力：分解复杂任务为可执行步骤 长期记忆：保存和检索历史交互信息 工具使用能力：调用外部API和工具 自我反思：评估执行结果并进行修正 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108from abc import ABC, abstractmethodfrom typing import List, Dict, Anyfrom dataclasses import dataclass, fieldfrom enum import Enumclass AgentStatus(Enum): IDLE = &quot;idle&quot; THINKING = &quot;thinking&quot; ACTING = &quot;acting&quot; WAITING = &quot;waiting&quot; FINISHED = &quot;finished&quot; ERROR = &quot;error&quot;@dataclassclass Thought: &quot;&quot;&quot;Agent思考过程&quot;&quot;&quot; thought: str action: str observation: str = &quot;&quot; result: Any = None@dataclassclass AgentState: &quot;&quot;&quot;Agent状态&quot;&quot;&quot; status: AgentStatus = AgentStatus.IDLE memory: List[str] = field(default_factory=list) history: List[Thought] = field(default_factory=list) current_goal: str = &quot;&quot; pending_tasks: List[str] = field(default_factory=list)class BaseAgent(ABC): &quot;&quot;&quot; AI Agent基础抽象类 &quot;&quot;&quot; def __init__(self, name: str, llm, max_iterations: int = 100): self.name = name self.llm = llm self.max_iterations = max_iterations self.state = AgentState() @abstractmethod def think(self, context: str) -&gt; Thought: &quot;&quot;&quot;思考：分析情况，决定下一步行动&quot;&quot;&quot; pass @abstractmethod def act(self, thought: Thought) -&gt; str: &quot;&quot;&quot;行动：执行决定的行动&quot;&quot;&quot; pass @abstractmethod def observe(self, result: str) -&gt; str: &quot;&quot;&quot;观察：分析行动结果&quot;&quot;&quot; pass def remember(self, info: str): &quot;&quot;&quot;记忆：将信息存入长期记忆&quot;&quot;&quot; self.state.memory.append(info) def recall(self, query: str) -&gt; List[str]: &quot;&quot;&quot;回忆：从记忆中检索相关信息&quot;&quot;&quot; # 简单的关键词匹配，实际可用向量检索 relevant = [m for m in self.state.memory if query.lower() in m.lower()] return relevant def run(self, goal: str) -&gt; str: &quot;&quot;&quot; Agent主循环 &quot;&quot;&quot; self.state.current_goal = goal self.state.status = AgentStatus.THINKING for i in range(self.max_iterations): # 1. 思考 context = self._build_context() thought = self.think(context) self.state.history.append(thought) # 2. 行动 self.state.status = AgentStatus.ACTING result = self.act(thought) # 3. 观察 self.state.status = AgentStatus.WAITING observation = self.observe(result) # 4. 记忆 self.remember(f&quot;Action: &#123;thought.action&#125;, Result: &#123;result&#125;&quot;) # 5. 检查是否完成 if self._is_goal_achieved(observation): self.state.status = AgentStatus.FINISHED return observation self.state.status = AgentStatus.THINKING self.state.status = AgentStatus.ERROR return &quot;达到最大迭代次数，任务未完成&quot; def _build_context(self) -&gt; str: &quot;&quot;&quot;构建思考上下文&quot;&quot;&quot; context = f&quot;Goal: &#123;self.state.current_goal&#125;

&quot; context += &quot;Recent memory:
&quot; + &quot;
&quot;.join(self.state.memory[-5:]) return context def _is_goal_achieved(self, observation: str) -&gt; bool: &quot;&quot;&quot;检查目标是否达成&quot;&quot;&quot; return &quot;完成&quot; in observation or &quot;成功&quot; in observation or &quot;达成&quot; in observation AutoGPT架构解析1. AutoGPT核心实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102class AutoGPT(BaseAgent): &quot;&quot;&quot; AutoGPT实现 基于GPT-4的自主代理系统 &quot;&quot;&quot; def __init__(self, llm, tools: List[Callable], memory_backend=None): super().__init__(&quot;AutoGPT&quot;, llm) self.tools = tools self.tool_schemas = self._generate_tool_schemas() self.memory = memory_backend or InMemoryMemory() def _generate_tool_schemas(self) -&gt; str: &quot;&quot;&quot;生成工具描述&quot;&quot;&quot; schemas = [] for tool in self.tools: schemas.append(f&quot;- &#123;tool.name&#125;: &#123;tool.description&#125;&quot;) return &quot;
&quot;.join(schemas) def think(self, context: str) -&gt; Thought: &quot;&quot;&quot; 使用LLM进行思考和规划 &quot;&quot;&quot; prompt = f&quot;&quot;&quot;你是一个AI助手，正在帮助用户完成任务。当前目标：&#123;self.state.current_goal&#125;可用工具：&#123;self.tool_schemas&#125;历史操作：&#123;self._format_history()&#125;请分析当前情况，决定下一步行动。返回格式：思考：...行动：工具名称参数：&#123;&#123;&quot;参数名&quot;: &quot;参数值&quot;&#125;&#125;&quot;&quot;&quot; response = self.llm.generate(prompt) thought = self._parse_response(response) return thought def act(self, thought: Thought) -&gt; str: &quot;&quot;&quot; 执行选定的工具 &quot;&quot;&quot; tool_name = thought.action args = thought.result or &#123;&#125; for tool in self.tools: if tool.name == tool_name: try: result = tool(**args) return str(result) except Exception as e: return f&quot;工具执行失败: &#123;str(e)&#125;&quot; return f&quot;未找到工具: &#123;tool_name&#125;&quot; def observe(self, result: str) -&gt; str: &quot;&quot;&quot; 分析执行结果 &quot;&quot;&quot; prompt = f&quot;&quot;&quot;分析以下执行结果，判断目标是否达成：目标：&#123;self.state.current_goal&#125;执行结果：&#123;result&#125;请判断：1. 目标是否已达成？2. 如果未达成，还需哪些步骤？&quot;&quot;&quot; analysis = self.llm.generate(prompt) return analysis def _format_history(self) -&gt; str: &quot;&quot;&quot;格式化历史记录&quot;&quot;&quot; return &quot;
&quot;.join([ f&quot;- &#123;h.thought&#125; -&gt; &#123;h.action&#125;&quot; for h in self.state.history[-5:] ]) def _parse_response(self, response: str) -&gt; Thought: &quot;&quot;&quot;解析LLM响应&quot;&quot;&quot; lines = response.split(&quot;
&quot;) thought = Thought(thought=&quot;&quot;, action=&quot;&quot;, observation=&quot;&quot;) for line in lines: if line.startswith(&quot;思考：&quot;): thought.thought = line[3:].strip() elif line.startswith(&quot;行动：&quot;): thought.action = line[3:].strip() elif line.startswith(&quot;参数：&quot;): import json try: thought.result = json.loads(line[3:].strip()) except: thought.result = &#123;&#125; return thought 2. 工具系统设计123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100from typing import Callableimport requestsimport jsonclass Tool: &quot;&quot;&quot;工具基类&quot;&quot;&quot; def __init__(self, name: str, description: str): self.name = name self.description = description def __call__(self, **kwargs): raise NotImplementedErrorclass GoogleSearchTool(Tool): &quot;&quot;&quot;Google搜索工具&quot;&quot;&quot; def __init__(self): super().__init__( name=&quot;google_search&quot;, description=&quot;搜索Google获取最新信息，输入查询字符串，返回搜索结果摘要&quot; ) def __call__(self, query: str, num_results: int = 5) -&gt; str: # 实际项目中需要使用Google API results = self._search_google(query, num_results) return &quot;
&quot;.join([ f&quot;&#123;i+1&#125;. &#123;r[&#x27;title&#x27;]&#125;
 &#123;r[&#x27;snippet&#x27;]&#125;&quot; for i, r in enumerate(results) ]) def _search_google(self, query: str, num: int): # 模拟实现 return [ &#123;&quot;title&quot;: f&quot;结果&#123;i+1&#125;&quot;, &quot;snippet&quot;: f&quot;关于&#123;query&#125;的信息...&quot;&#125; for i in range(num) ]class WebScraperTool(Tool): &quot;&quot;&quot;网页抓取工具&quot;&quot;&quot; def __init__(self): super().__init__( name=&quot;web_scraper&quot;, description=&quot;抓取指定URL的网页内容，返回页面文本&quot; ) def __call__(self, url: str) -&gt; str: try: response = requests.get(url, timeout=10) return self._extract_text(response.text) except Exception as e: return f&quot;抓取失败: &#123;str(e)&#125;&quot; def _extract_text(self, html: str) -&gt; str: # 简单的HTML文本提取 import re text = re.sub(r&#x27;&lt;script.*?&lt;/script&gt;&#x27;, &#x27;&#x27;, html, flags=re.DOTALL) text = re.sub(r&#x27;&lt;style.*?&lt;/style&gt;&#x27;, &#x27;&#x27;, text, flags=re.DOTALL) text = re.sub(r&#x27;&lt;[^&gt;]+&gt;&#x27;, &#x27;&#x27;, text) return text[:5000] # 限制长度class FileWriteTool(Tool): &quot;&quot;&quot;文件写入工具&quot;&quot;&quot; def __init__(self, base_path: str = &quot;./outputs&quot;): super().__init__( name=&quot;file_write&quot;, description=&quot;将内容写入文件&quot; ) self.base_path = base_path def __call__(self, filename: str, content: str) -&gt; str: import os os.makedirs(self.base_path, exist_ok=True) filepath = os.path.join(self.base_path, filename) with open(filepath, &#x27;w&#x27;, encoding=&#x27;utf-8&#x27;) as f: f.write(content) return f&quot;文件已保存: &#123;filepath&#125;&quot;class CodeExecutorTool(Tool): &quot;&quot;&quot;代码执行工具&quot;&quot;&quot; def __init__(self): super().__init__( name=&quot;code_executor&quot;, description=&quot;执行Python代码，返回执行结果&quot; ) def __call__(self, code: str) -&gt; str: try: import io from contextlib import redirect_stdout output = io.StringIO() exec(code, &#123;&#x27;__name__&#x27;: &#x27;__main__&#x27;&#125;) with redirect_stdout(output): exec(code) return output.getvalue() or &quot;代码执行成功，无输出&quot; except Exception as e: return f&quot;执行错误: &#123;str(e)&#125;&quot; BabyAGI实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106class BabyAGI: &quot;&quot;&quot; BabyAGI：简化的目标驱动代理 &quot;&quot;&quot; def __init__(self, objective: str, llm): self.objective = objective self.llm = llm self.task_list = [] self.completed_tasks = [] def add_task(self, task: str): &quot;&quot;&quot;添加任务&quot;&quot;&quot; self.task_list.append(&#123;&quot;content&quot;: task, &quot;task_id&quot;: len(self.task_list) + 1&#125;) def get_next_task(self, result: str) -&gt; str: &quot;&quot;&quot;根据结果确定下一个任务&quot;&quot;&quot; prompt = f&quot;&quot;&quot;分析以下任务执行结果，确定下一步应该做什么。原始目标：&#123;self.objective&#125;执行结果：&#123;result&#125;已完成任务：&#123;len(self.completed_tasks)&#125;当前待处理任务：&#123;len(self.task_list)&#125;如果执行结果已实现目标，返回&quot;STOP&quot;。否则，返回下一步应该执行的任务描述。&quot;&quot;&quot; response = self.llm.generate(prompt).strip() if &quot;STOP&quot; in response: return None return response def task_creation_chain(self, result: str) -&gt; str: &quot;&quot;&quot;创建新任务&quot;&quot;&quot; prompt = f&quot;&quot;&quot;基于执行结果，创建新的子任务。目标：&#123;self.objective&#125;结果：&#123;result&#125;请列出需要完成的具体子任务，每个任务一行。&quot;&quot;&quot; response = self.llm.generate(prompt) # 解析任务列表 tasks = [] for line in response.split(&quot;
&quot;): line = line.strip() if line and (line[0].isdigit() or line.startswith(&quot;-&quot;)): task = line.lstrip(&quot;0123456789.- &quot;).strip() if task: tasks.append(task) return tasks def prioritize_tasks(self, tasks: List[str]): &quot;&quot;&quot;任务优先级排序&quot;&quot;&quot; self.task_list = [&#123;&quot;content&quot;: t, &quot;task_id&quot;: i&#125; for i, t in enumerate(tasks)] def execute_task(self, task: str) -&gt; str: &quot;&quot;&quot;执行单个任务&quot;&quot;&quot; prompt = f&quot;&quot;&quot;执行以下任务，并详细描述执行过程和结果。任务：&#123;task&#125;执行结果：&quot;&quot;&quot; result = self.llm.generate(prompt) return result def run(self): &quot;&quot;&quot;BabyAGI主循环&quot;&quot;&quot; print(f&quot;🎯 目标: &#123;self.objective&#125;
&quot;) # 初始化任务列表 initial_tasks = self.task_creation_chain(&quot;开始&quot;) self.prioritize_tasks(initial_tasks) while self.task_list: # 获取下一个任务 current_task = self.task_list.pop(0) print(f&quot;📋 执行任务: &#123;current_task[&#x27;content&#x27;]&#125;&quot;) # 执行任务 result = self.execute_task(current_task[&#x27;content&#x27;]) print(f&quot;📤 结果: &#123;result[:200]&#125;...
