&quot;.join(self.completed_tasks) 多代理系统架构12345678910111213141516171819202122232425262728293031323334353637383940414243444546class MultiAgentSystem: &quot;&quot;&quot; 多代理协作系统 &quot;&quot;&quot; def __init__(self): self.agents: Dict[str, BaseAgent] = &#123;&#125; self.message_queue = Queue() def register_agent(self, name: str, agent: BaseAgent): &quot;&quot;&quot;注册代理&quot;&quot;&quot; self.agents[name] = agent def send_message(self, from_agent: str, to_agent: str, message: str): &quot;&quot;&quot;代理间通信&quot;&quot;&quot; self.message_queue.put(&#123; &quot;from&quot;: from_agent, &quot;to&quot;: to_agent, &quot;content&quot;: message &#125;) def broadcast(self, from_agent: str, message: str): &quot;&quot;&quot;广播消息&quot;&quot;&quot; for name, agent in self.agents.items(): if name != from_agent: self.send_message(from_agent, name, message) def coordinate(self): &quot;&quot;&quot; 协调多个代理协作 &quot;&quot;&quot; # 示例：规划代理 + 执行代理 planner = self.agents.get(&quot;planner&quot;) executor = self.agents.get(&quot;executor&quot;) if planner and executor: # 规划 plan = planner.think(&quot;制定执行计划&quot;) # 广播计划 self.broadcast(&quot;planner&quot;, str(plan)) # 执行 result = executor.act(plan) # 反馈 planner.observe(result) 应用场景1. 自动化研究助手123456789101112131415161718192021222324252627class ResearchAgent(AutoGPT): &quot;&quot;&quot; 自动化研究助手 &quot;&quot;&quot; def __init__(self, llm): tools = [ GoogleSearchTool(), WebScraperTool(), FileWriteTool(&quot;./research_output&quot;) ] super().__init__(llm, tools) def research_topic(self, topic: str, depth: int = 3) -&gt; str: &quot;&quot;&quot; 自动化研究主题 &quot;&quot;&quot; goal = f&quot;&quot;&quot;对&#x27;&#123;topic&#125;&#x27;进行深入研究，包括： 1. 定义和背景 2. 最新研究进展 3. 主要技术方法 4. 应用场景 5. 未来发展趋势 输出完整的研究报告到 research_report.md &quot;&quot;&quot; return self.run(goal) 2. 智能开发助手1234567891011121314151617181920212223242526class CodeAssistantAgent(AutoGPT): &quot;&quot;&quot; 智能代码开发助手 &quot;&quot;&quot; def __init__(self, llm): tools = [ CodeExecutorTool(), FileWriteTool(&quot;./code_output&quot;), GoogleSearchTool() # 查文档 ] super().__init__(llm, tools) def develop_feature(self, description: str) -&gt; str: &quot;&quot;&quot; 根据描述开发功能 &quot;&quot;&quot; goal = f&quot;&quot;&quot;开发以下功能： &#123;description&#125; 1. 分析需求 2. 编写代码 3. 编写测试 4. 验证功能 &quot;&quot;&quot; return self.run(goal) 总结AI Agent代表了人工智能从”回答问题”到”自主行动”的重要跨越。通过结合大模型的推理能力与工具使用能力，Agent能够完成复杂的自动化任务。AutoGPT和BabyAGI展示了这一技术的巨大潜力，同时也暴露出现有系统的局限性。随着技术的不断成熟，AI Agent将在科学研究、软件开发、业务自动化等领域发挥越来越重要的作用。 参考资源 AutoGPT GitHub BabyAGI GitHub LangChain Agents文档

引言检索增强生成（Retrieval-Augmented Generation, RAG）是2023年大模型应用领域的核心技术之一。RAG通过结合检索系统和生成模型，有效解决了大模型知识过时、幻觉问题等痛点。本文将深入剖析RAG的技术原理、架构设计和工程实现。 RAG技术原理1. 为什么需要RAG大语言模型存在以下固有问题： 知识截止日期：模型的训练数据有截止日期，无法获取最新信息 幻觉问题：模型可能生成看似合理但错误的内容 长尾知识缺失：训练数据不均衡导致长尾知识表现差 领域专业知识：垂直领域知识不足 RAG通过检索最新、最相关的信息来增强模型的回答质量。 2. RAG核心架构1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768from dataclasses import dataclassfrom typing import List, Optionalimport numpy as np@dataclassclass Document: &quot;&quot;&quot;文档数据结构&quot;&quot;&quot; page_content: str metadata: dictclass RAGSystem: &quot;&quot;&quot; RAG系统核心组件 &quot;&quot;&quot; def __init__(self, embedding_model, llm, vector_store): self.embedding_model = embedding_model # 嵌入模型 self.llm = llm # 语言模型 self.vector_store = vector_store # 向量数据库 def retrieve(self, query: str, top_k: int = 5) -&gt; List[Document]: &quot;&quot;&quot; 检索相关文档 &quot;&quot;&quot; # 将查询向量化 query_embedding = self.embedding_model.embed(query) # 在向量数据库中搜索 results = self.vector_store.similarity_search( query_embedding, k=top_k ) return results def generate(self, query: str, context_docs: List[Document]) -&gt; str: &quot;&quot;&quot; 基于检索结果生成回答 &quot;&quot;&quot; # 构建prompt context = &quot;

&quot;.join([ f&quot;[文档&#123;i+1&#125;] &#123;doc.page_content&#125;&quot; for i, doc in enumerate(context_docs) ]) prompt = f&quot;&quot;&quot;基于以下参考文档回答问题。如果文档中没有相关信息，请说明无法回答。参考文档：&#123;context&#125;问题：&#123;query&#125;回答：&quot;&quot;&quot; # 调用语言模型生成 response = self.llm.generate(prompt) return response def answer(self, query: str, top_k: int = 5) -&gt; str: &quot;&quot;&quot; RAG完整流程：检索 + 生成 &quot;&quot;&quot; # 1. 检索相关文档 docs = self.retrieve(query, top_k) # 2. 基于文档生成回答 response = self.generate(query, docs) return response 向量数据库详解1. Embedding模型选择12345678910111213141516171819202122232425from sentence_transformers import SentenceTransformerimport torchclass EmbeddingModel: &quot;&quot;&quot; Embedding模型封装 &quot;&quot;&quot; def __init__(self, model_name=&quot;moka-ai/m3e-base&quot;): self.model = SentenceTransformer(model_name) self.model.eval() # GPU加速 if torch.cuda.is_available(): self.model = self.model.to(&#x27;cuda&#x27;) def embed(self, text: str) -&gt; np.ndarray: &quot;&quot;&quot;单文本嵌入&quot;&quot;&quot; return self.model.encode(text, normalize_embeddings=True) def embed_batch(self, texts: List[str]) -&gt; np.ndarray: &quot;&quot;&quot;批量嵌入&quot;&quot;&quot; return self.model.encode(texts, normalize_embeddings=True, batch_size=32) def get_embedding_dim(self) -&gt; int: return self.model.get_sentence_embedding_dimension() 2. 向量索引实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970import faissimport numpy as npclass VectorIndex: &quot;&quot;&quot; FAISS向量索引 &quot;&quot;&quot; def __init__(self, dim: int, index_type=&quot;IVF&quot;): self.dim = dim self.index_type = index_type self.index = self._build_index() self.documents = [] # 存储原始文档 def _build_index(self): &quot;&quot;&quot; 构建索引 支持多种索引类型 &quot;&quot;&quot; if self.index_type == &quot;Flat&quot;: # 精确搜索，精度最高 return faiss.IndexFlatIP(self.dim) # 内积相似度 elif self.index_type == &quot;IVF&quot;: # 倒排索引，近似搜索 quantizer = faiss.IndexFlatIP(self.dim) return faiss.IndexIVFFlat(quantizer, self.dim, 100) elif self.index_type == &quot;HNSW&quot;: # 分层可导航小世界图 return faiss.IndexHNSWFlat(self.dim, 32) elif self.index_type == &quot;PQ&quot;: # 产品量化，压缩存储 return faiss.IndexPQ(self.dim, 16, 8) raise ValueError(f&quot;Unknown index type: &#123;self.index_type&#125;&quot;) def add(self, embeddings: np.ndarray, documents: List[Document]): &quot;&quot;&quot; 添加向量到索引 &quot;&quot;&quot; if not self.index.is_trained: # 训练索引 self.index.train(embeddings) # L2归一化用于余弦相似度 embeddings = embeddings / np.linalg.norm(embeddings, axis=1, keepdims=True) self.index.add(embeddings) self.documents.extend(documents) def search(self, query_embedding: np.ndarray, k: int = 5) -&gt; List[Document]: &quot;&quot;&quot; 相似性搜索 &quot;&quot;&quot; # 归一化 query = query_embedding / np.linalg.norm(query_embedding) # 搜索 distances, indices = self.index.search(query.reshape(1, -1), k) # 返回文档 results = [] for idx, dist in zip(indices[0], distances[0]): if idx &gt;= 0 and idx &lt; len(self.documents): doc = self.documents[idx] doc.metadata[&#x27;score&#x27;] = float(dist) results.append(doc) return results 3. Milvus向量数据库集成123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869from pymilvus import connections, Collection, FieldSchema, CollectionSchema, DataTypeclass MilvusVectorStore: &quot;&quot;&quot; Milvus向量数据库封装 &quot;&quot;&quot; def __init__(self, host=&quot;localhost&quot;, port=&quot;19530&quot;, collection_name=&quot;documents&quot;): connections.connect(host=host, port=port) self.collection_name = collection_name self._create_collection() def _create_collection(self): &quot;&quot;&quot;创建集合&quot;&quot;&quot; fields = [ FieldSchema(name=&quot;id&quot;, dtype=DataType.INT64, is_primary=True, auto_id=True), FieldSchema(name=&quot;embedding&quot;, dtype=DataType.FLOAT_VECTOR, dim=1536), FieldSchema(name=&quot;content&quot;, dtype=DataType.VARCHAR, max_length=65535), FieldSchema(name=&quot;metadata&quot;, dtype=DataType.VARCHAR, max_length=65535) ] schema = CollectionSchema(fields=fields, description=&quot;Document collection&quot;) self.collection = Collection(name=self.collection_name, schema=schema) # 创建索引 index_params = &#123; &quot;metric_type&quot;: &quot;IP&quot;, # 内积 &quot;index_type&quot;: &quot;IVF_FLAT&quot;, &quot;params&quot;: &#123;&quot;nlist&quot;: 128&#125; &#125; self.collection.create_index(field_name=&quot;embedding&quot;, index_params=index_params) def insert(self, embeddings: List[np.ndarray], documents: List[Document]): &quot;&quot;&quot;插入数据&quot;&quot;&quot; import json entities = [ embeddings.tolist(), [doc.page_content for doc in documents], [json.dumps(doc.metadata) for doc in documents] ] self.collection.insert(entities) self.collection.flush() def search(self, query_embedding: np.ndarray, top_k: int = 5) -&gt; List[Document]: &quot;&quot;&quot;搜索&quot;&quot;&quot; import json search_params = &#123;&quot;metric_type&quot;: &quot;IP&quot;, &quot;params&quot;: &#123;&quot;nprobe&quot;: 10&#125;&#125; results = self.collection.search( data=[query_embedding.tolist()], anns_field=&quot;embedding&quot;, param=search_params, limit=top_k, output_fields=[&quot;content&quot;, &quot;metadata&quot;] ) docs = [] for hits in results: for hit in hits: doc = Document( page_content=hit.entity.get(&quot;content&quot;), metadata=json.loads(hit.entity.get(&quot;metadata&quot;)) ) doc.metadata[&#x27;score&#x27;] = hit.score docs.append(doc) return docs LangChain RAG实战1. 文档加载与处理1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556from langchain.document_loaders import PyPDFLoader, UnstructuredHTMLLoaderfrom langchain.text_splitter import RecursiveCharacterTextSplitterfrom langchain.embeddings import HuggingFaceEmbeddingsclass DocumentProcessor: &quot;&quot;&quot; 文档处理流水线 &quot;&quot;&quot; def __init__(self, chunk_size=500, chunk_overlap=50): self.text_splitter = RecursiveCharacterTextSplitter( chunk_size=chunk_size, chunk_overlap=chunk_overlap, separators=[&quot;

&quot;, &quot;
&quot;, &quot;。&quot;, &quot;！&quot;, &quot;？&quot;, &quot; &quot;] ) self.embeddings = HuggingFaceEmbeddings( model_name=&quot;moka-ai/m3e-base&quot;, model_kwargs=&#123;&#x27;device&#x27;: &#x27;cuda&#x27;&#125; ) def load_pdf(self, file_path: str) -&gt; List[Document]: &quot;&quot;&quot;加载PDF&quot;&quot;&quot; loader = PyPDFLoader(file_path) pages = loader.load_and_split() # 分割 docs = self.text_splitter.split_documents(pages) return docs def load_html(self, file_path: str) -&gt; List[Document]: &quot;&quot;&quot;加载HTML&quot;&quot;&quot; loader = UnstructuredHTMLLoader(file_path) docs = loader.load() docs = self.text_splitter.split_documents(docs) return docs def load_webpage(self, url: str) -&gt; List[Document]: &quot;&quot;&quot;加载网页&quot;&quot;&quot; from langchain.document_loaders import WebBaseLoader loader = WebBaseLoader(url) docs = loader.load() docs = self.text_splitter.split_documents(docs) return docs def create_vectorstore(self, documents: List[Document], persist_dir: str = None): &quot;&quot;&quot;创建向量数据库&quot;&quot;&quot; from langchain.vectorstores import Chroma # 使用Chroma存储 vectorstore = Chroma.from_documents( documents=documents, embedding=self.embeddings, persist_directory=persist_dir ) return vectorstore 2. RAG Chain构建1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980from langchain.chains import RetrievalQAfrom langchain.prompts import PromptTemplatefrom langchain.chat_models import ChatOpenAIclass RAGChainBuilder: &quot;&quot;&quot; 构建RAG Chain &quot;&quot;&quot; def __init__(self, vectorstore, llm_model=&quot;gpt-3.5-turbo&quot;): self.vectorstore = vectorstore self.llm = ChatOpenAI(model=llm_model, temperature=0) def build_qa_chain(self): &quot;&quot;&quot; 构建问答Chain &quot;&quot;&quot; prompt_template = &quot;&quot;&quot;使用以下背景信息回答问题。如果信息不足以回答问题，请说明不知道，不要编造答案。背景信息：&#123;context&#125;问题：&#123;question&#125;回答：&quot;&quot;&quot; PROMPT = PromptTemplate( template=prompt_template, input_variables=[&quot;context&quot;, &quot;question&quot;] ) chain = RetrievalQA.from_chain_type( llm=self.llm, chain_type=&quot;stuff&quot;, # 将所有文档拼接到prompt retriever=self.vectorstore.as_retriever( search_kwargs=&#123;&quot;k&quot;: 5&#125; ), chain_type_kwargs=&#123; &quot;prompt&quot;: PROMPT, &quot;document_variable_name&quot;: &quot;context&quot; &#125; ) return chain def build_conversational_chain(self): &quot;&quot;&quot; 构建对话Chain（支持多轮对话） &quot;&quot;&quot; from langchain.chains import ConversationalRetrievalChain from langchain.memory import ConversationBufferMemory memory = ConversationBufferMemory( memory_key=&quot;chat_history&quot;, return_messages=True ) chain = ConversationalRetrievalChain.from_llm( llm=self.llm, retriever=self.vectorstore.as_retriever(), memory=memory, condense_question_prompt=self._get_condense_prompt() ) return chain def _get_condense_prompt(self): &quot;&quot;&quot; 获取问题改写prompt 将对话历史+新问题改写为独立问题 &quot;&quot;&quot; template = &quot;&quot;&quot;给定以下对话历史和一个后续问题，将后续问题重新表述为一个独立的问题，使其包含足够的上下文信息。对话历史：&#123;chat_history&#125;后续问题：&#123;question&#125;独立问题：&quot;&quot;&quot; return PromptTemplate.from_template(template) 3. HyDE：假设性文档嵌入123456789101112131415161718192021222324252627282930313233343536class HyDERetrieval: &quot;&quot;&quot; HyDE (Hypothetical Document Embeddings) 通过生成假设性文档来改进检索 &quot;&quot;&quot; def __init__(self, embedding_model, llm): self.embedding_model = embedding_model self.llm = llm def generate_hypothetical_document(self, query: str) -&gt; str: &quot;&quot;&quot; 生成假设性答案文档 &quot;&quot;&quot; prompt = f&quot;&quot;&quot;针对以下问题，生成一个假设性的答案文档。这个文档应该是一个可能的正确答案，然后根据这个假设文档进行检索。问题：&#123;query&#125;假设性答案文档：&quot;&quot;&quot; hyp_doc = self.llm.generate(prompt) return hyp_doc def retrieve(self, query: str, vectorstore, top_k: int = 5): &quot;&quot;&quot; HyDE检索流程 &quot;&quot;&quot; # 1. 生成假设性文档 hyp_doc = self.generate_hypothetical_document(query) # 2. 向量化假设文档 hyp_embedding = self.embedding_model.embed(hyp_doc) # 3. 使用假设文档检索 results = vectorstore.similarity_search(hyp_embedding, k=top_k) return results RAG高级技巧1. 重排序（Reranking）1234567891011121314151617181920212223242526from sentence_transformers import CrossEncoderclass Reranker: &quot;&quot;&quot; 使用Cross-Encoder进行重排序 &quot;&quot;&quot; def __init__(self, model_name=&quot;BAAI/bge-reranker-base&quot;): self.model = CrossEncoder(model_name) def rerank(self, query: str, documents: List[Document], top_k: int = 3): &quot;&quot;&quot; 重排序检索结果 &quot;&quot;&quot; doc_texts = [doc.page_content for doc in documents] # 构建查询-文档对 pairs = [(query, doc) for doc in doc_texts] # 计算相关性分数 scores = self.model.predict(pairs) # 按分数排序 scored_docs = list(zip(documents, scores)) scored_docs.sort(key=lambda x: x[1], reverse=True) return [doc for doc, score in scored_docs[:top_k]] 2. 混合检索12345678910111213141516171819202122232425262728293031323334353637class HybridRetrieval: &quot;&quot;&quot; 混合检索：向量检索 + BM25关键词检索 &quot;&quot;&quot; def __init__(self, vectorstore, bm25_index): self.vectorstore = vectorstore self.bm25_index = bm25_index def retrieve(self, query: str, top_k: int = 5, vector_weight: float = 0.7): &quot;&quot;&quot; 混合检索 &quot;&quot;&quot; # 向量检索 vector_results = self.vectorstore.similarity_search(query, k=top_k * 2) # BM25检索 bm25_results = self.bm25_index.search(query, k=top_k * 2) # 分数归一化和融合 fused_scores = &#123;&#125; for doc, score in vector_results: doc_id = doc.metadata.get(&#x27;id&#x27;, id(doc)) fused_scores[doc_id] = fused_scores.get(doc_id, 0) + score * vector_weight for doc, score in bm25_results: doc_id = doc.metadata.get(&#x27;id&#x27;, id(doc)) fused_scores[doc_id] = fused_scores.get(doc_id, 0) + score * (1 - vector_weight) # 排序返回 sorted_docs = sorted( fused_scores.items(), key=lambda x: x[1], reverse=True )[:top_k] return [doc for doc, _ in sorted_docs] 总结RAG是解决大模型知识局限性的一种有效方案。通过结合向量检索和语言模型生成，RAG系统能够提供最新、最准确的回答。本文介绍了RAG的核心原理、向量数据库选择、LangChain实现以及多项高级优化技巧。在实际应用中，需要根据具体场景选择合适的检索策略和模型配置，以达到最佳的问答效果。 参考资源 L