引言ChatGLM是由清华大学KEG实验室和智谱AI联合开发的中英双语大语言模型。作为国产开源大模型的代表，ChatGLM在中文理解与生成方面表现出色，并已广泛应用于工业界。本文将深入分析ChatGLM的技术架构、训练方法和部署实践。 ChatGLM技术架构1. GLM核心设计ChatGLM基于通用语言模型（General Language Model, GLM）架构，这是一种结合了自编码和自回归优势的混合目标函数： 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778import torchimport torch.nn as nnfrom transformers import PretrainedConfigclass GLMAttention(nn.Module): &quot;&quot;&quot; GLM的自注意力机制 支持长短混合注意力模式 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.hidden_size = config.hidden_size self.num_heads = config.num_attention_heads self.head_dim = self.hidden_size // self.num_heads # 旋转位置编码 self.rotary_emb = RotaryEmbedding(self.head_dim) # 注意力投影 self.query_key_value = nn.Linear( config.hidden_size, 3 * config.hidden_size ) self.dense = nn.Linear(config.hidden_size, config.hidden_size) def forward(self, hidden_states, position_ids, attention_mask=None): B, L, _ = hidden_states.shape # QKV投影 qkv = self.query_key_value(hidden_states) qkv = qkv.reshape(B, L, 3, self.num_heads, self.head_dim) q, k, v = qkv.unbind(2) # 应用RoPE q, k = self.rotary_emb(q, k, position_ids) # 计算注意力 attn_output = self._attn(q, k, v, attention_mask) return self.dense(attn_output) def _attn(self, q, k, v, attention_mask): scale = 1.0 / (self.head_dim ** 0.5) attn_weights = torch.matmul(q, k.transpose(-2, -1)) * scale if attention_mask is not None: attn_weights = attn_weights + attention_mask attn_weights = nn.functional.softmax(attn_weights, dim=-1) return torch.matmul(attn_weights, v)class GLMBlock(nn.Module): &quot;&quot;&quot; GLM Transformer Block &quot;&quot;&quot; def __init__(self, config): super().__init__() self.attention = GLMAttention(config) self.mlp = nn.Sequential( nn.Linear(config.hidden_size, config.intermediate_size * 4), nn.GELU(), nn.Linear(config.intermediate_size * 4, config.hidden_size) ) self.post_attention_layernorm = nn.LayerNorm(config.hidden_size) def forward(self, hidden_states, position_ids, attention_mask=None): # 自注意力 + 残差 residual = hidden_states hidden_states = self.attention(hidden_states, position_ids, attention_mask) hidden_states = residual + hidden_states # 前馈网络 + 残差 residual = hidden_states hidden_states = self.post_attention_layernorm(hidden_states) hidden_states = self.mlp(hidden_states) hidden_states = residual + hidden_states return hidden_states 2. Prefix LM训练范式ChatGLM采用Prefix LM训练范式，支持不同注意力模式： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071class PrefixLMConfig: def __init__(self): self.num_layers = 28 self.hidden_size = 4096 self.num_attention_heads = 32 self.pre_seq_len = 128 # Prefix序列长度 self.virtual_pipeline_parallel_size = 1class PrefixLMModel(nn.Module): &quot;&quot;&quot; Prefix LM支持双向注意力和单向注意力的混合 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.num_layers = config.num_layers self.prefix_tokens = config.pre_seq_len # 词嵌入 self.embedding = nn.Embedding(config.vocab_size, config.hidden_size) # Prefix编码器 self.prefix_encoder = nn.Sequential( nn.Linear(config.hidden_size, config.hidden_size), nn.Tanh(), nn.Linear(config.hidden_size, config.num_layers * 2 * config.hidden_size) ) # Transformer层 self.layers = nn.ModuleList([ GLMBlock(config) for _ in range(config.num_layers) ]) def get_position_ids(self, input_ids, seq_len, past_key_values_length=0): &quot;&quot;&quot; 生成位置编码 &quot;&quot;&quot; mask = input_ids == 150_004 # [MASK] token positions = torch.cumsum(mask, dim=1).type_as(mask) + past_key_values_length - 1 positions = positions - positions.where(~mask).max(-1, keepdim=True)[0] + past_key_values_length return positions def forward(self, input_ids, attention_mask=None): B, L = input_ids.shape # 获取embedding hidden_states = self.embedding(input_ids) # 生成prefix注意力 prefix_attention = self.get_prefix_attention(input_ids) # 生成位置编码 position_ids = self.get_position_ids(input_ids, L) # 通过Transformer层 for layer in self.layers: hidden_states = layer( hidden_states, position_ids, attention_mask=prefix_attention ) return hidden_states def get_prefix_attention(self, input_ids): &quot;&quot;&quot; 为prefix tokens生成特殊注意力掩码 &quot;&quot;&quot; B, L = input_ids.shape # Prefix tokens之间双向注意，其他单向 prefix_mask = (input_ids == 150_004).unsqueeze(1).unsqueeze(2) return prefix_mask ChatGLM训练流程1. 预训练阶段1234567891011121314151617181920212223242526272829303132333435363738394041class ChatGLMPretraining: &quot;&quot;&quot; ChatGLM预训练配置 &quot;&quot;&quot; def __init__(self): self.optimizer_config = &#123; &quot;learning_rate&quot;: 1e-4, &quot;weight_decay&quot;: 0.1, &quot;beta1&quot;: 0.9, &quot;beta2&quot;: 0.999, &quot;warmup_steps&quot;: 2000 &#125; self.training_config = &#123; &quot;batch_size&quot;: 8, &quot;sequence_length&quot;: 2048, &quot;gradient_accumulation_steps&quot;: 16, &quot;max_steps&quot;: 100_000 &#125; def compute_loss(self, model, batch): &quot;&quot;&quot; GLM的预训练损失 Token级别的语言建模损失 &quot;&quot;&quot; input_ids = batch[&#x27;input_ids&#x27;] labels = batch[&#x27;labels&#x27;] outputs = model(input_ids) logits = outputs.logits # Shift logits and labels for causal LM shift_logits = logits[..., :-1, :].contiguous() shift_labels = labels[..., 1:].contiguous() loss_fct = nn.CrossEntropyLoss() loss = loss_fct( shift_logits.view(-1, shift_logits.size(-1)), shift_labels.view(-1) ) return loss 2. SFT监督微调12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667class ChatGLMSFT: &quot;&quot;&quot; ChatGLM监督微调 &quot;&quot;&quot; def __init__(self, model, tokenizer): self.model = model self.tokenizer = tokenizer def format_prompt(self, conversation): &quot;&quot;&quot; 格式化对话prompt &quot;&quot;&quot; prompt = &quot;&quot; for turn in conversation: role = turn[&#x27;role&#x27;] content = turn[&#x27;content&#x27;] if role == &#x27;user&#x27;: prompt += f&quot;[Round &#123;turn[&#x27;round&#x27;]&#125;]
问：&#123;content&#125;
&quot; else: prompt += f&quot;答：&#123;content&#125;
&quot; prompt += &quot;答：&quot; return prompt def sft_collate_fn(self, batch): &quot;&quot;&quot; SFT数据整理 &quot;&quot;&quot; prompts = [self.format_prompt(conv) for conv in batch[&#x27;conversation&#x27;]] encoded = self.tokenizer( prompts, padding=True, truncation=True, max_length=2048, return_tensors=&#x27;pt&#x27; ) return &#123; &#x27;input_ids&#x27;: encoded[&#x27;input_ids&#x27;], &#x27;attention_mask&#x27;: encoded[&#x27;attention_mask&#x27;], &#x27;labels&#x27;: encoded[&#x27;input_ids&#x27;].clone() &#125; def train(self, train_dataset, output_dir): from transformers import Trainer, TrainingArguments training_args = TrainingArguments( output_dir=output_dir, per_device_train_batch_size=4, gradient_accumulation_steps=4, learning_rate=1e-5, num_train_epochs=3, logging_steps=10, save_steps=1000, save_total_limit=3, fp16=True, dataloader_num_workers=4 ) trainer = Trainer( model=self.model, args=training_args, train_dataset=train_dataset, data_collator=self.sft_collate_fn ) trainer.train() 3. PPO强化学习训练12345678910111213141516171819202122232425262728293031323334353637383940class ChatGLMPPOTrainer: &quot;&quot;&quot; ChatGLM的RLHF训练 &quot;&quot;&quot; def __init__(self, ref_model, reward_model, ppo_config): self.ref_model = ref_model self.reward_model = reward_model self.ppo_config = ppo_config def compute_reward(self, response, prompt): &quot;&quot;&quot; 使用奖励模型计算reward &quot;&quot;&quot; full_text = prompt + response reward_score = self.reward_model(full_text) return reward_score def compute_kl_penalty(self, response, prompt): &quot;&quot;&quot; KL散度惩罚，防止过度优化 &quot;&quot;&quot; with torch.no_grad(): ref_log_probs = self.ref_model(prompt + response).log_probs new_log_probs = self.model(prompt + response).log_probs return ref_log_probs - new_log_probs def ppo_step(self, prompts, responses): &quot;&quot;&quot; PPO更新步骤 &quot;&quot;&quot; rewards = [] kl_penalties = [] for prompt, response in zip(prompts, responses): reward = self.compute_reward(response, prompt) kl = self.compute_kl_penalty(response, prompt) rewards.append(reward - self.ppo_config.kl_coef * kl) kl_penalties.append(kl) # PPO策略更新... ChatGLM6B部署实践1. 量化部署12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152from transformers import AutoModel, AutoTokenizerimport torchclass ChatGLMDeployer: def __init__(self, model_path, quantize_mode=&#x27;int4&#x27;): self.tokenizer = AutoTokenizer.from_pretrained(model_path, trust_remote_code=True) load_kwargs = &#123; &quot;trust_remote_code&quot;: True, &quot;device_map&quot;: &quot;auto&quot; &#125; if quantize_mode == &#x27;int4&#x27;: # INT4量化，大幅降低显存占用 self.model = AutoModel.from_pretrained( model_path, quantization_config=BitsAndBytesConfig( load_in_4bit=True, bnb_4bit_compute_dtype=torch.float16 ), **load_kwargs ) elif quantize_mode == &#x27;int8&#x27;: self.model = AutoModel.from_pretrained( model_path, quantization_config=BitsAndBytesConfig( load_in_8bit=True ), **load_kwargs ) else: self.model = AutoModel.from_pretrained(model_path, **load_kwargs) def chat(self, query, history=None, max_length=2048): response, history = self.model.chat( self.tokenizer, query, history=history or [], max_length=max_length ) return response, history def stream_chat(self, query, history=None): &quot;&quot;&quot; 流式输出 &quot;&quot;&quot; for response, history in self.model.stream_chat( self.tokenizer, query, history=history or [] ): yield response 2. OpenAI兼容API12345678910111213141516171819202122232425262728293031323334353637383940414243from fastapi import FastAPIfrom pydantic import BaseModelimport uvicornapp = FastAPI(title=&quot;ChatGLM API&quot;)class ChatRequest(BaseModel): prompt: str history: list = [] max_length: int = 2048 temperature: float = 0.7@app.post(&quot;/v1/chat/completions&quot;)async def chat_completions(request: ChatRequest): response, _ = chatglm.chat( request.prompt, request.history, request.max_length ) return &#123; &quot;choices&quot;: [&#123; &quot;message&quot;: &#123; &quot;role&quot;: &quot;assistant&quot;, &quot;content&quot;: response &#125;, &quot;finish_reason&quot;: &quot;stop&quot;, &quot;index&quot;: 0 &#125;], &quot;usage&quot;: &#123; &quot;prompt_tokens&quot;: len(request.prompt), &quot;completion_tokens&quot;: len(response), &quot;total_tokens&quot;: len(request.prompt) + len(response) &#125; &#125;@app.get(&quot;/health&quot;)async def health(): return &#123;&quot;status&quot;: &quot;ok&quot;&#125;# 启动服务if __name__ == &quot;__main__&quot;: uvicorn.run(app, host=&quot;0.0.0.0&quot;, port=8000) ChatGLM产业应用智能客服系统1234567891011121314151617181920212223242526272829class ChatGLMCustomerService: def __init__(self, model_path): self.llm = ChatGLMDeployer(model_path) self.context_db = vector_db # 知识库 def retrieve_context(self, query): &quot;&quot;&quot; 检索相关知识 &quot;&quot;&quot; relevant_docs = self.context_db.similarity_search(query, k=3) context = &quot;
&quot;.join([doc.page_content for doc in relevant_docs]) return context def generate_response(self, query, user_id): # 检索相关知识 context = self.retrieve_context(query) # 构建prompt prompt = f&quot;&quot;&quot;基于以下知识回答用户问题： 知识库内容：&#123;context&#125;用户问题：&#123;query&#125;回答：&quot;&quot;&quot; response, _ = self.llm.chat(prompt) return response 总结ChatGLM作为国产大模型的优秀代表，在中文理解与生成方面展现了强大的能力。通过GLM架构创新、Prefix LM训练范式和完整的RLHF流程，ChatGLM实现了卓越的性能。开源的ChatGLM-6B更是降低了中文大模型的应用门槛，推动了国内AI生态的快速发展。 参考资源 ChatGLM项目主页 GLM论文 Hugging Face ChatGLM

引言2023年2月，Meta（原Facebook）发布了LLaMA（Large Language Model Meta AI），这是开源大语言模型领域的重要里程碑。LLaMA系列不仅为研究者提供了强大的工具，更推动了开源AI生态的快速发展。本文将深入分析LLaMA的技术架构、训练方法和实际部署方案。 LLaMA的技术架构1. 基础架构设计LLaMA采用了标准的Transformer解码器架构，但在多个方面进行了优化： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980818283848586878889import torchimport torch.nn as nnimport mathclass RMSNorm(nn.Module): &quot;&quot;&quot; RMSNorm：更高效的正则化方法 LLaMA使用RMSNorm替代LayerNorm，提升训练稳定性 &quot;&quot;&quot; def __init__(self, hidden_size, eps=1e-6): super().__init__() self.weight = nn.Parameter(torch.ones(hidden_size)) self.variance_epsilon = eps def forward(self, hidden_states): input_dtype = hidden_states.dtype hidden_states = hidden_states.to(torch.float32) variance = hidden_states.pow(2).mean(-1, keepdim=True) hidden_states = hidden_states * torch.rsqrt(variance + self.variance_epsilon) return self.weight * hidden_states.to(input_dtype)class LLaMAAttention(nn.Module): &quot;&quot;&quot; LLaMA的自注意力机制，使用RoPE位置编码 &quot;&quot;&quot; def __init__(self, config): super().__init__() self.n_heads = config.n_heads self.head_dim = config.hidden_size // config.n_heads self.max_position_embeddings = config.max_position_embeddings # Query, Key, Value投影 self.q_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=False) self.k_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=False) self.v_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=False) self.o_proj = nn.Linear(config.hidden_size, config.hidden_size, bias=False) # RoPE (Rotary Position Embedding) self.rotary_emb = RotaryEmbedding(self.head_dim) def forward(self, x, attention_mask=None): B, T, C = x.shape # 投影得到QKV q = self.q_proj(x).view(B, T, self.n_heads, self.head_dim).transpose(1, 2) k = self.k_proj(x).view(B, T, self.n_heads, self.head_dim).transpose(1, 2) v = self.v_proj(x).view(B, T, self.n_heads, self.head_dim).transpose(1, 2) # 应用RoPE q, k = self.rotary_emb(q, k) # 计算注意力分数 attn_weights = torch.matmul(q, k.transpose(-2, -1)) / math.sqrt(self.head_dim) if attention_mask is not None: attn_weights = attn_weights + attention_mask attn_weights = nn.functional.softmax(attn_weights, dim=-1) attn_output = torch.matmul(attn_weights, v) return self.o_proj(attn_output.transpose(1, 2).contiguous().view(B, T, C))class RotaryEmbedding(nn.Module): &quot;&quot;&quot; Rotary Position Embedding (RoPE) 旋转位置编码，有效处理位置信息 &quot;&quot;&quot; def __init__(self, dim, max_position_embeddings=2048): super().__init__() inv_freq = 1.0 / (10000 ** (torch.arange(0, dim, 2).float() / dim)) self.register_buffer(&quot;inv_freq&quot;, inv_freq) def forward(self, q, k): B, n_heads, T, head_dim = q.shape t = torch.arange(T, device=q.device).type_as(self.inv_freq) freqs = torch.einsum(&quot;i,j-&gt;ij&quot;, t, self.inv_freq) emb = torch.cat((freqs, freqs), dim=-1) # 旋转操作 q_embed = self._rotate_half(q, emb) k_embed = self._rotate_half(k, emb) return q_embed, k_embed def _rotate_half(self, x, emb): x1, x2 = x[..., :x.shape[-1]//2], x[..., x.shape[-1]//2:] return torch.cat((-x2, x1), dim=-1) * self._get_cos_sin(emb) def _get_cos_sin(self, emb): return torch.cos(emb), torch.sin(emb) 2. SwiGLU激活函数LLaMA使用SwiGLU替代ReLU，显著提升了模型性能： 1234567891011121314class SwiGLU(nn.Module): &quot;&quot;&quot; SwiGLU激活函数 Swish(x) * Gate(x) 的变体，提升非线性表达能力 &quot;&quot;&quot; def __init__(self, hidden_size, intermediate_size): super().__init__() self.w1 = nn.Linear(hidden_size, intermediate_size, bias=False) self.w2 = nn.Linear(hidden_size, intermediate_size, bias=False) self.w3 = nn.Linear(intermediate_size, hidden_size, bias=False) self.act_fn = nn.SiLU() def forward(self, x): return self.w3(self.act_fn(self.w1(x)) * self.w2(x)) LLaMA模型变体LLaMA提供多个参数规模的模型版本： 模型规模 参数量 隐藏层维度 注意力头数 适用场景 LLaMA-7B 7B 4096 32 研究实验 LLaMA-13B 13B 5120 40 日常应用 LLaMA-33B 33B 6656 52 专业部署 LLaMA-65B 65B 8192 64 大规模推理 LLaMA2：新一代开源大模型2023年7月，Meta发布了LLaMA2，带来了多项重大改进： 1. 训练数据扩展LLaMA2使用了约2万亿tokens的训练数据，比LLaMA1增加了40%。 2. 更长的上下文窗口LLaMA2将上下文窗口扩展到4096 tokens，支持更长的对话和文档处理。 3. RLHF对齐训练123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657class RLHFTrainer: &quot;&quot;&quot; 人类反馈强化学习训练器 用于LLaMA2的对齐训练 &quot;&quot;&quot; def __init__(self, model, reward_model, ref_model): self.model = model self.reward_model = reward_model # 奖励模型 self.ref_model = ref_model # 参考模型（原始模型） self.ppo_config = PPOConfig( steps=20000, lr=1.4e-5, batch_size=512, mini_batch_size=4, gradient_accumulation_steps=8 ) def compute_rewards(self, responses, prompts): &quot;&quot;&quot; 计算 responses 的奖励分数 &quot;&quot;&quot; # 使用奖励模型评估 full_texts = [p + r for p, r in zip(prompts, responses)] reward_scores = self.reward_model(full_texts) return reward_scores def compute_kl_divergence(self, responses, prompts): &quot;&quot;&quot; 计算与参考模型的KL散度，防止过度优化 &quot;&quot;&quot; with torch.no_grad(): ref_log_probs = self.ref_model(prompts + responses) new_log_probs = self.model(prompts + responses) return ref_log_probs - new_log_probs def ppo_update(self, batch): &quot;&quot;&quot; PPO算法更新 &quot;&quot;&quot; prompts = batch[&#x27;prompts&#x27;] responses = batch[&#x27;responses&#x27;] # 获取奖励和KL散度 rewards = self.compute_rewards(responses, prompts) kl_divs = self.compute_kl_divergence(responses, prompts) # 计算 advantage advantages = rewards - 0.1 * kl_divs # KL惩罚 # 策略更新 for _ in range(self.ppo_config.ppo_epochs): logits = self.model(prompts + responses) # PPO裁剪更新... def train(self, training_data): for batch in DataLoader(training_data, batch_size=self.ppo_config.batch_size): self.ppo_update(batch) LLaMA部署实战1. 使用llama.cpp量化部署123456789101112# 安装llama.cppgit clone https://github.com/ggerganov/llama.cpp.gitcd llama.cppmkdir build &amp;&amp; cd buildcmake ..make -j4# 量化模型./quantize ../models/llama-7b/ggml-model-f16.bin ../models/llama-7b/ggml-model-q4_0.bin q4_0# 运行推理./main -m ../models/llama-7b/ggml-model-q4_0.bin -n 256 -t 8 -p &quot;The meaning of life is&quot; 2. Python推理接口123456789101112131415161718192021222324252627282930313233343536373839404142from llama_cpp import Llamaclass LLaMAInference: def __init__(self, model_path, n_ctx=2048, n_threads=4): self.llm = Llama( model_path=model_path, n_ctx=n_ctx, n_threads=n_threads, n_gpu_layers=0 # CPU推理 ) def generate(self, prompt, max_tokens=256, temperature=0.7, top_p=0.95): output = self.llm( prompt, max_tokens=max_tokens, temperature=temperature, top_p=top_p, echo=False, stop=[&quot;&lt;/s&gt;&quot;, &quot;User:&quot;, &quot;

&quot;] ) return output[&#x27;choices&#x27;][0][&#x27;text&#x27;] def chat(self, messages, system_prompt=&quot;You are a helpful assistant&quot;): # 构建对话 prompt prompt = f&quot;&#123;system_prompt&#125;

&quot; for msg in messages: role = msg[&#x27;role&#x27;] content = msg[&#x27;content&#x27;] if role == &#x27;user&#x27;: prompt += f&quot;User: &#123;content&#125;
&quot; else: prompt += f&quot;Assistant: &#123;content&#125;
&quot; prompt += &quot;Assistant: &quot; return self.generate(prompt) def batch_generate(self, prompts, max_tokens=256): &quot;&quot;&quot; 批量生成，提高吞吐量 &quot;&quot;&quot; outputs = self.llm.create_batch(prompts, max_tokens=max_tokens) return [out[&#x27;choices&#x27;][0][&#x27;text&#x27;] for out in outputs] 3. 使用transformers部署123456789101112131415161718192021222324252627282930313233343536373839404142434445from transformers import AutoModelForCausalLM, AutoTokenizerimport torchclass LLaMAWithTransformers: def __init__(self, model_name=&quot;meta-llama/Llama-2-7b-hf&quot;): self.tokenizer = AutoTokenizer.from_pretrained(model_name) self.model = AutoModelForCausalLM.from_pretrained( model_name, torch_dtype=torch.float16, device_map=&quot;auto&quot; ) def generate(self, prompt, max_new_tokens=256): inputs = self.tokenizer(prompt, return_tensors=&quot;pt&quot;).to(&quot;cuda&quot;) with torch.no_grad(): outputs = self.model.generate( **inputs, max_new_tokens=max_new_tokens, do_sample=True, temperature=0.7, top_p=0.9 ) return self.tokenizer.decode(outputs[0], skip_special_tokens=True) def fine_tune(self, train_data, output_dir=&quot;./llama-finetuned&quot;): &quot;&quot;&quot; 使用LoRA进行轻量级微调 &quot;&quot;&quot; from peft import LoraConfig, get_peft_model, TaskType lora_config = LoraConfig( r=8, lora_alpha=16, target_modules=[&quot;q_proj&quot;, &quot;v_proj&quot;], lora_dropout=0.05, bias=&quot;none&quot;, task_type=TaskType.CAUSAL_LM ) self.model = get_peft_model(self.model, lora_config) self.model.print_trainable_parameters() # 训练代码... LLaMA生态工具链1. LangChain集成1234567891011121314from langchain.llms import LlamaCppfrom langchain.chains import ConversationalChainfrom langchain.memory import ConversationBufferMemorydef create_llama_chain(model_path): llm = LlamaCpp(model_path=model_path, verbose=False) chain = ConversationalChain.from_llm( llm=llm, memory=ConversationBufferMemory(), prompt_template=&quot;&#123;history&#125;
User: &#123;input&#125;
AI:&quot; ) return chain 总结LLaMA系列代表了开源大语言模型的重要成就。从LLaMA到LLaMA2，Meta不断推动开源AI技术的边界。通过合理的量化压缩和部署策略，LLaMA可以在消费级硬件上运行，为开发者和研究者提供了强大的工具。随着开源社区的持续贡献，LLaMA生态系统将变得更加丰富和完善。 参考资源 LLaMA论文 LLaMA2论文 llama.cpp GitHub Hugging Face LLaMA

ChatBot对话系统构建实战2022年，基于大模型的ChatBot成为最热门的AI应用方向。从简单的FAQ机器人到具备知识检索能力的智能助手，本文将手把手教你构建一个完整的对话系统。 1. 对话系统架构graph TB A[用户消息] --> B[消息预处理] B --> C[意图识别] C --> D{意图类型} D -->|闲聊| E[LLM直接生成] D -->|知识问答| F[RAG检索增强] D -->|任务执行| G[Function Call] F --> F1[查询向量化] F1 --> F2[向量数据库检索] F2 --> F3[上下文增强] F3 --> H[LLM生成回答] G --> G1[参数提取] G1 --> G2[调用API] G2 --> G3[结果格式化] G3 --> H E --> H H --> I[后处理与安全检查] I --> J[返回用户] K[对话记忆] --> C K --> H 2. 基础对话管理2.1 对话状态管理123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869from dataclasses import dataclass, fieldfrom typing import List, Dict, Optionalfrom datetime import datetimeimport uuid@dataclassclass Message: role: str # user / assistant / system content: str timestamp: datetime = field(default_factory=datetime.now) metadata: Dict = field(default_factory=dict)class ConversationManager: &quot;&quot;&quot;对话状态管理器&quot;&quot;&quot; def __init__(self, max_history=20): self.conversations: Dict[str, List[Message]] = &#123;&#125; self.max_history = max_history def create_conversation(self, system_prompt=None) -&gt; str: &quot;&quot;&quot;创建新对话，返回对话ID&quot;&quot;&quot; conv_id = str(uuid.uuid4()) self.conversations[conv_id] = [] if system_prompt: self.conversations[conv_id].append( Message(role=&quot;system&quot;, content=system_prompt) ) return conv_id def add_message(self, conv_id: str, role: str, content: str): &quot;&quot;&quot;添加消息到对话历史&quot;&quot;&quot; if conv_id not in self.conversations: self.conversations[conv_id] = [] self.conversations[conv_id].append( Message(role=role, content=content) ) # 保持历史在限制内 if len(self.conversations[conv_id]) &gt; self.max_history: # 保留system消息和最近的对话 msgs = self.conversations[conv_id] system_msgs = [m for m in msgs if m.role == &quot;system&quot;] other_msgs = [m for m in msgs if m.role != &quot;system&quot;] self.conversations[conv_id] = system_msgs + other_msgs[-self.max_history:] def get_messages(self, conv_id: str) -&gt; List[Dict]: &quot;&quot;&quot;获取对话历史（API格式）&quot;&quot;&quot; if conv_id not in self.conversations: return [] return [ &#123;&quot;role&quot;: m.role, &quot;content&quot;: m.content&#125; for m in self.conversations[conv_id] ] def get_summary(self, conv_id: str) -&gt; str: &quot;&quot;&quot;生成对话摘要（用于长对话压缩）&quot;&quot;&quot; messages = self.conversations.get(conv_id, []) if len(messages) &lt;= 10: return &quot;&quot; # 提取关键信息 topics = set() for m in messages: if m.role == &quot;user&quot;: topics.add(m.content[:50]) return f&quot;之前讨论过: &#123;&#x27;, &#x27;.join(list(topics)[:5])&#125;&quot; 2.2 基础聊天接口1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465import openaiclass ChatBot: &quot;&quot;&quot;基础聊天机器人&quot;&quot;&quot; def __init__(self, model=&quot;gpt-3.5-turbo&quot;, system_prompt=None): self.model = model self.system_prompt = system_prompt or &quot;你是一个友好且专业的AI助手。&quot; self.conv_manager = ConversationManager() def chat(self, user_input: str, conv_id: str = None, temperature=0.7, **kwargs) -&gt; str: &quot;&quot;&quot;对话主入口&quot;&quot;&quot; # 创建或获取对话 if conv_id is None: conv_id = self.conv_manager.create_conversation(self.system_prompt) # 添加用户消息 self.conv_manager.add_message(conv_id, &quot;user&quot;, user_input) # 获取完整对话历史 messages = self.conv_manager.get_messages(conv_id) # 调用LLM response = openai.ChatCompletion.create( model=self.model, messages=messages, temperature=temperature, **kwargs ) assistant_reply = response.choices[0].message.content # 保存助手回复 self.conv_manager.add_message(conv_id, &quot;assistant&quot;, assistant_reply) return assistant_reply def stream_chat(self, user_input: str, conv_id: str = None): &quot;&quot;&quot;流式输出&quot;&quot;&quot; if conv_id is None: conv_id = self.conv_manager.create_conversation(self.system_prompt) self.conv_manager.add_message(conv_id, &quot;user&quot;, user_input) messages = self.conv_manager.get_messages(conv_id) full_reply = &quot;&quot; for chunk in openai.ChatCompletion.create( model=self.model, messages=messages, stream=True ): content = chunk.choices[0].delta.get(&quot;content&quot;, &quot;&quot;) if content: full_reply += content yield content self.conv_manager.add_message(conv_id, &quot;assistant&quot;, full_reply)# 使用示例bot = ChatBot(system_prompt=&quot;你是一个Python编程专家，擅长解释技术概念。&quot;)conv_id = bot.conv_manager.create_conversation(&quot;你是一个Python编程专家&quot;)print(bot.chat(&quot;什么是装饰器？&quot;, conv_id=conv_id))print(bot.chat(&quot;能举个例子吗？&quot;, conv_id=conv_id)) # 记住上文 3. RAG增强的对话系统123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869from langchain.embeddings import OpenAIEmbeddingsfrom langchain.vectorstores import FAISSfrom langchain.text_splitter import RecursiveCharacterTextSplitterfrom langchain.document_loaders import PyPDFLoader, DirectoryLoaderclass RAGChatBot(ChatBot): &quot;&quot;&quot;具备知识检索能力的ChatBot&quot;&quot;&quot; def __init__(self, knowledge_dir=&quot;./knowledge&quot;, **kwargs): super().__init__(**kwargs) self.knowledge_dir = knowledge_dir self.vectorstore = None self._build_knowledge_base() def _build_knowledge_base(self): &quot;&quot;&quot;构建知识库&quot;&quot;&quot; print(&quot;正在构建知识库...&quot;) # 加载文档 loader = DirectoryLoader( self.knowledge_dir, glob=&quot;**/*.&#123;pdf,txt,md&#125;&quot;, show_progress=True ) docs = loader.load() # 切分 splitter = RecursiveCharacterTextSplitter( chunk_size=500, chunk_overlap=50, separators=[&quot;

&quot;, &quot;
&quot;, &quot;。&quot;, &quot; &quot;, &quot;&quot;] ) splits = splitter.split_documents(docs) # 向量化 embeddings = OpenAIEmbeddings() self.vectorstore = FAISS.from_documents(splits, embeddings) print(f&quot;知识库构建完成，共 &#123;len(splits)&#125; 个文档块&quot;) def chat(self, user_input: str, conv_id: str = None, use_rag=True, top_k=4, **kwargs) -&gt; str: &quot;&quot;&quot;带RAG的对话&quot;&quot;&quot; if conv_id is None: conv_id = self.conv_manager.create_conversation(self.system_prompt) # 检索相关知识 context = &quot;&quot; if use_rag and self.vectorstore: relevant_docs = self.vectorstore.similarity_search( user_input, k=top_k ) context = &quot;

&quot;.join([ f&quot;[来源&#123;i+1&#125;]: &#123;doc.page_content&#125;&quot; for i, doc in enumerate(relevant_docs) ]) # 构建增强prompt if context: enhanced_input = f&quot;&quot;&quot;基于以下参考资料回答用户问题。如果参考资料中没有相关信息，请根据你的知识回答，并说明这不是来自知识库。参考资料：&#123;context&#125;用户问题：&#123;user_input&#125;&quot;&quot;&quot; else: enhanced_input = user_input return super().chat(enhanced_input, conv_id=conv_id, **kwargs) 4. 多技能ChatBot123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990import jsonimport reclass SkillChatBot(RAGChatBot): &quot;&quot;&quot;具备多种技能的ChatBot&quot;&quot;&quot; def __init__(self, **kwargs): super().__init__(**kwargs) self.skills = &#123;&#125; self._register_skills() def _register_skills(self): &quot;&quot;&quot;注册技能&quot;&quot;&quot; self.skills = &#123; &quot;calculate&quot;: &#123; &quot;description&quot;: &quot;执行数学计算&quot;, &quot;pattern&quot;: r&quot;计算[：:]?\s*(.+)&quot;, &quot;handler&quot;: self._handle_calculate &#125;, &quot;search_knowledge&quot;: &#123; &quot;description&quot;: &quot;搜索知识库&quot;, &quot;pattern&quot;: r&quot;(什么是|解释|介绍).+&quot;, &quot;handler&quot;: self._handle_search &#125;, &quot;code_generate&quot;: &#123; &quot;description&quot;: &quot;生成代码&quot;, &quot;pattern&quot;: r&quot;(写|编写|生成|实现).*(代码|函数|程序|脚本)&quot;, &quot;handler&quot;: self._handle_code &#125;, &quot;translate&quot;: &#123; &quot;description&quot;: &quot;翻译文本&quot;, &quot;pattern&quot;: r&quot;(翻译|translate).+&quot;, &quot;handler&quot;: self._handle_translate &#125; &#125; def _route_skill(self, user_input: str): &quot;&quot;&quot;路由到合适的技能&quot;&quot;&quot; for skill_name, skill in self.skills.items(): if re.search(skill[&quot;pattern&quot;], user_input): return skill[&quot;handler&quot;] return None # 无匹配，走默认LLM def chat(self, user_input: str, conv_id: str = None, **kwargs): &quot;&quot;&quot;带技能路由的对话&quot;&quot;&quot; handler = self._route_skill(user_input) if handler: return handler(user_input, conv_id, **kwargs) # 默认走RAG增强对话 return super().chat(user_input, conv_id=conv_id, **kwargs) def _handle_calculate(self, user_input, conv_id, **kwargs): &quot;&quot;&quot;处理数学计算&quot;&quot;&quot; expr = re.search(r&quot;计算[：:]?\s*(.+)&quot;, user_input) if expr: try: # 安全计算（仅允许数学运算） import ast result = ast.literal_eval(expr.group(1)) return f&quot;计算结果：&#123;result&#125;&quot; except: return &quot;无法计算该表达式，请检查格式是否正确&quot; return &quot;请提供要计算的表达式&quot; def _handle_search(self, user_input, conv_id, **kwargs): &quot;&quot;&quot;处理知识检索&quot;&quot;&quot; return super().chat(user_input, conv_id=conv_id, use_rag=True, **kwargs) def _handle_code(self, user_input, conv_id, **kwargs): &quot;&quot;&quot;处理代码生成&quot;&quot;&quot; enhanced = f&quot;&quot;&quot;请生成代码来满足以下需求。要求：1. 代码包含完整的功能实现2. 添加必要的注释3. 包含错误处理4. 附带使用示例需求：&#123;user_input&#125;&quot;&quot;&quot; return super().chat(enhanced, conv_id=conv_id, use_rag=False, temperature=0.3, **kwargs) def _handle_translate(self, user_input, conv_id, **kwargs): &quot;&quot;&quot;处理翻译&quot;&quot;&quot; enhanced = f&quot;&quot;&quot;请翻译以下内容，先自动检测语言，然后翻译为另一种语言：&#123;user_input&#125;&quot;&quot;&quot; return super().chat(enhanced, conv_id=conv_id, use_rag=False, temperature=0.3, **kwargs) 5. Web界面搭建123456789101112131415161718192021222324252627282930313233343536373839404142434445from fastapi import FastAPI, WebSocketfrom fastapi.middleware.cors import CORSMiddlewareimport asyncioapp = FastAPI(title=&quot;AI ChatBot API&quot;)app.add_middleware(CORSMiddleware, allow_origins=[&quot;*&quot;], allow_methods=[&quot;*&quot;], allow_headers=[&quot;*&quot;])bot = SkillChatBot( knowledge_dir=&quot;./knowledge&quot;, system_prompt=&quot;你是一个专业的AI助手，能够回答技术问题、生成代码、翻译文本。&quot;)@app.post(&quot;/chat&quot;)async def chat_endpoint(request: dict): &quot;&quot;&quot;REST API聊天端点&quot;&quot;&quot; user_input = request.get(&quot;message&quot;, &quot;&quot;) conv_id = request.get(&quot;conversation_id&quot;, None) reply = bot.chat(user_input, conv_id=conv_id) return &#123; &quot;reply&quot;: reply, &quot;conversation_id&quot;: conv_id or list(bot.conv_manager.conversations.keys())[-1] &#125;@app.websocket(&quot;/ws/chat&quot;)async def websocket_chat(websocket: WebSocket): &quot;&quot;&quot;WebSocket流式聊天端点&quot;&quot;&quot; await websocket.accept() conv_id = bot.conv_manager.create_conversation(bot.system_prompt) try: while True: data = await websocket.receive_text() # 流式输出 for chunk in bot.stream_chat(data, conv_id=conv_id): await websocket.send_json(&#123;&quot;chunk&quot;: chunk&#125;) await websocket.send_json(&#123;&quot;done&quot;: True&#125;) except Exception as e: print(f&quot;WebSocket错误: &#123;e&#125;&quot;)# 启动: uvicorn chatbot_api:app --host 0.0.0.0 --port 8000 6. 安全与防护12345678910111213141516171819202122232425class SafetyChecker: &quot;&quot;&quot;输出安全检查&quot;&quot;&quot; # 敏感模式 PATTERNS = &#123; &quot;pii&quot;: r&quot;(\d&#123;18&#125;|\d&#123;17&#125;[Xx])&quot;, # 身份证号 &quot;phone&quot;: r&quot;1[3-9]\d&#123;9&#125;&quot;, # 手机号 &quot;email&quot;: r&quot;[\w.-]+@[\w.-]+\.\w+&quot;, # 邮箱 &quot;api_key&quot;: r&quot;[A-Za-z0-9]&#123;32,&#125;&quot;, # API密钥 &#125; def check(self, text: str) -&gt; tuple: &quot;&quot;&quot;检查文本是否安全&quot;&quot;&quot; for category, pattern in self.PATTERNS.items(): if re.search(pattern, text): return False, f&quot;检测到敏感信息: &#123;category&#125;&quot; return True, &quot;安全&quot; def sanitize(self, text: str) -&gt; str: &quot;&quot;&quot;脱敏处理&quot;&quot;&quot; text = re.sub(self.PATTERNS[&quot;pii&quot;], &quot;[身份证号已隐藏]&quot;, text) text = re.sub(self.PATTERNS[&quot;phone&quot;], &quot;[手机号已隐藏]&quot;, text) text = re.sub(self.PATTERNS[&quot;email&quot;], &quot;[邮箱已隐藏]&quot;, text) text = re.sub(self.PATTERNS[&quot;api_key&quot;], &quot;[API密钥已隐藏]&quot;, text) return text 总结构建一个完整的ChatBot需要对话管理、RAG检索增强、技能路由和Web服务等多个模块的协同。2022年的大模型使得构建高质量ChatBot的门槛大幅降低，但系统的工程化设计——状态管理、安全防护、流式输出——仍然是决定产品质量的关键。

LangChain大模型应用开发框架LangChain是2022年最受关注的LLM应用开发框架，它提供了一套标准化接口来构建基于大语言模型的复杂应用，从简单的问答系统到具备工具使用能力的自主代理。 1. LangChain架构概览graph TB subgraph "LangChain核心组件" A[Models] --> B[LLM/ChatModel接口] C[Prompts] --> D[模板管理/少样本] E[Chains] --> F[调用序列编排] G[Agents] --> H[工具选择与执行] I[Memory] --> J[对话状态管理] K[Retrieval] --> L[文档检索/RAG] end subgraph "数据源" M[PDF/HTML/TXT] N[数据库/API] O[向量数据库] end M --> K N --> H O --> K subgraph "应用" P[ChatBot] Q[文档问答] R[自主代理] end F --> P K --> Q H --> R 2. 核心模块使用2.1 Models - 模型接口12345678910111213141516from langchain.llms import OpenAIfrom langchain.chat_models import ChatOpenAIfrom langchain.schema import HumanMessage, SystemMessage, AIMessage# 文本补全模型llm = OpenAI(model_name=&quot;text-davinci-003&quot;, temperature=0.7)result = llm(&quot;什么是机器学习？用一句话概括。&quot;)# 聊天模型（推荐）chat = ChatOpenAI(model=&quot;gpt-3.5-turbo&quot;, temperature=0.7)messages = [ SystemMessage(content=&quot;你是一个AI技术专家&quot;), HumanMessage(content=&quot;解释Transformer的self-attention机制&quot;),]response = chat(messages)print(response.content) 2.2 Prompts - 提示词管理1234567891011121314151617181920212223242526272829303132333435363738from langchain.prompts import ( PromptTemplate, ChatPromptTemplate, FewShotPromptTemplate)# 基础模板template = PromptTemplate.from_template( &quot;请为&#123;product&#125;写一段&#123;style&#125;风格的推广文案，字数在&#123;word_count&#125;字以内。&quot;)prompt = template.format( product=&quot;AI编程助手&quot;, style=&quot;科技感&quot;, word_count=200)# 聊天模板chat_template = ChatPromptTemplate.from_messages([ (&quot;system&quot;, &quot;你是一个&#123;role&#125;，擅长&#123;expertise&#125;&quot;), (&quot;human&quot;, &quot;&#123;question&#125;&quot;),])# Few-Shot模板examples = [ &#123;&quot;input&quot;: &quot;开心&quot;, &quot;output&quot;: &quot;😊 快乐的情绪，通常伴随着微笑和愉悦感&quot;&#125;, &#123;&quot;input&quot;: &quot;悲伤&quot;, &quot;output&quot;: &quot;😢 低落的情绪，通常伴随着失落和沮丧感&quot;&#125;,]few_shot_prompt = FewShotPromptTemplate( prefix=&quot;分析以下情感词的含义和特征：&quot;, examples=examples, example_prompt=PromptTemplate( input_variables=[&quot;input&quot;, &quot;output&quot;], template=&quot;词: &#123;input&#125;
分析: &#123;output&#125;&quot; ), suffix=&quot;词: &#123;word&#125;
分析:&quot;, input_variables=[&quot;word&quot;]) 2.3 Chains - 调用链1234567891011121314151617181920212223242526272829303132from langchain.chains import LLMChain, SimpleSequentialChain, RetrievalQA# 基础链chain = LLMChain( llm=chat, prompt=chat_template, verbose=True # 打印中间过程)# 顺序链：多个步骤串联title_chain = LLMChain( llm=chat, prompt=PromptTemplate.from_template(&quot;为以下主题生成文章标题：&#123;topic&#125;&quot;))outline_chain = LLMChain( llm=chat, prompt=PromptTemplate.from_template(&quot;根据标题生成文章大纲：&#123;title&#125;&quot;))content_chain = LLMChain( llm=chat, prompt=PromptTemplate.from_template(&quot;根据大纲写一篇800字的文章：&#123;outline&#125;&quot;))# 串联执行overall_chain = SimpleSequentialChain( chains=[title_chain, outline_chain, content_chain], verbose=True)article = overall_chain.run(&quot;2022年AI技术发展趋势&quot;) 2.4 Memory - 记忆管理123456789101112131415161718192021222324252627from langchain.memory import ( ConversationBufferMemory, ConversationBufferWindowMemory, ConversationSummaryMemory)from langchain.chains import ConversationChain# 方式1：完整对话历史memory_full = ConversationBufferMemory()# 方式2：滑动窗口（只保留最近K轮）memory_window = ConversationBufferWindowMemory(k=5)# 方式3：摘要记忆（压缩历史对话）memory_summary = ConversationSummaryMemory(llm=chat)# 使用记忆的对话链conversation = ConversationChain( llm=chat, memory=memory_window, verbose=True)# 多轮对话conversation.predict(input=&quot;你好，我叫小明&quot;)conversation.predict(input=&quot;我最近在学习Python&quot;)conversation.predict(input=&quot;我刚才说我叫什么名字？&quot;) # 能记住&quot;小明&quot; 3. RAG - 检索增强生成RAG是LangChain最核心的应用模式，将外部知识库与LLM结合： graph LR A[用户问题] --> B[问题Embedding] B --> C[向量数据库检索] C --> D[相关文档片段] D --> E[构建增强Prompt] A --> E E --> F[LLM生成回答] 3.1 文档加载与切分1234567891011121314151617181920212223242526272829303132from langchain.document_loaders import ( PyPDFLoader, TextLoader, UnstructuredHTMLLoader, DirectoryLoader)from langchain.text_splitter import ( RecursiveCharacterTextSplitter, TokenTextSplitter)# 加载PDFpdf_loader = PyPDFLoader(&quot;ai_technology_report.pdf&quot;)pdf_docs = pdf_loader.load()# 批量加载目录dir_loader = DirectoryLoader( &quot;./documents&quot;, glob=&quot;**/*.pdf&quot;, loader_cls=PyPDFLoader)all_docs = dir_loader.load()# 文本切分text_splitter = RecursiveCharacterTextSplitter( chunk_size=1000, # 每块最大1000字符 chunk_overlap=200, # 块之间重叠200字符 separators=[&quot;

&quot;, &quot;
&quot;, &quot;。&quot;, &quot;！&quot;, &quot;？&quot;, &quot; &quot;, &quot;&quot;])splits = text_splitter.split_documents(all_docs)print(f&quot;原始文档: &#123;len(all_docs)&#125;个, 切分后: &#123;len(splits)&#125;个块&quot;) 3.2 向量化与存储123456789101112131415161718192021222324252627282930from langchain.embeddings import OpenAIEmbeddingsfrom langchain.vectorstores import Chroma, FAISS# 创建Embeddingembeddings = OpenAIEmbeddings()# 使用Chroma向量数据库vectorstore = Chroma.from_documents( documents=splits, embedding=embeddings, persist_directory=&quot;./chroma_db&quot;)# 或使用FAISS（纯内存，速度快）vectorstore = FAISS.from_documents(splits, embeddings)# 保存和加载vectorstore.save_local(&quot;./faiss_index&quot;)loaded_vs = FAISS.load_local(&quot;./faiss_index&quot;, embeddings)# 相似性检索results = vectorstore.similarity_search( &quot;什么是Transformer模型？&quot;, k=5 # 返回最相关的5个片段)for doc in results: print(f&quot;来源: &#123;doc.metadata[&#x27;source&#x27;]&#125;&quot;) print(f&quot;内容: &#123;doc.page_content[:200]&#125;...&quot;) print(&quot;---&quot;) 3.3 完整RAG问答系统12345678910111213141516171819202122232425262728293031323334353637from langchain.chains import RetrievalQAfrom langchain.prompts import PromptTemplate# 自定义QA提示模板qa_template = &quot;&quot;&quot;请基于以下参考资料回答问题。如果参考资料中没有相关信息，请回答&quot;根据已有资料无法回答此问题&quot;。参考资料：&#123;context&#125;问题：&#123;question&#125;回答：&quot;&quot;&quot;qa_prompt = PromptTemplate( template=qa_template, input_variables=[&quot;context&quot;, &quot;question&quot;])# 构建RAG链qa_chain = RetrievalQA.from_chain_type( llm=chat, chain_type=&quot;stuff&quot;, # stuff/map_reduce/refine retriever=vectorstore.as_retriever( search_type=&quot;mmr&quot;, # 最大边际相关性 search_kwargs=&#123;&quot;k&quot;: 5&#125; ), return_source_documents=True, chain_type_kwargs=&#123;&quot;prompt&quot;: qa_prompt&#125;)# 提问result = qa_chain(&#123;&quot;query&quot;: &quot;RLHF训练分为哪几个阶段？&quot;&#125;)print(f&quot;回答: &#123;result[&#x27;result&#x27;]&#125;&quot;)print(f&quot;
来源文档:&quot;)for doc in result[&#x27;source_documents&#x27;]: print(f&quot; - &#123;doc.metadata[&#x27;source&#x27;]&#125;&quot;) 4. Agent - 智能代理123456789101112131415161718192021222324252627282930313233343536373839404142434445from langchain.agents import ( AgentExecutor, create_react_agent, Tool)from langchain import SerpAPIWrapper, WikipediaAPIWrapper# 定义工具tools = [ Tool( name=&quot;Search&quot;, func=SerpAPIWrapper().run, description=&quot;用于搜索互联网上的最新信息，输入应该是搜索查询&quot; ), Tool( name=&quot;Calculator&quot;, func=lambda x: eval(x), description=&quot;用于数学计算，输入应该是数学表达式&quot; ), Tool( name=&quot;Wikipedia&quot;, func=WikipediaAPIWrapper().run, description=&quot;用于查询百科知识，输入应该是查询关键词&quot; ),]# 创建ReAct Agentagent = create_react_agent( llm=chat, tools=tools, prompt=None # 使用默认ReAct提示)agent_executor = AgentExecutor( agent=agent, tools=tools, verbose=True, max_iterations=10, handle_parsing_errors=True)# 执行任务result = agent_executor.run( &quot;2022年诺贝尔物理学奖获得者是谁？他们的主要贡献是什么？&quot;) 5. 完整应用：文档问答ChatBot12345678910111213141516171819202122232425262728293031323334353637383940414243444546from langchain.chains import ConversationalRetrievalChaindef build_doc_chatbot(docs_dir, model_name=&quot;gpt-3.5-turbo&quot;): &quot;&quot;&quot;构建完整的文档问答ChatBot&quot;&quot;&quot; # 1. 加载文档 loader = DirectoryLoader(docs_dir, glob=&quot;**/*.pdf&quot;, loader_cls=PyPDFLoader) docs = loader.load() # 2. 切分 splitter = RecursiveCharacterTextSplitter(chunk_size=1000, chunk_overlap=200) splits = splitter.split_documents(docs) # 3. 向量化 embeddings = OpenAIEmbeddings() vectorstore = FAISS.from_documents(splits, embeddings) # 4. 构建对话检索链 chat = ChatOpenAI(model=model_name, temperature=0) qa_chain = ConversationalRetrievalChain.from_llm( llm=chat, retriever=vectorstore.as_retriever(search_kwargs=&#123;&quot;k&quot;: 4&#125;), return_source_documents=True, memory=ConversationBufferMemory( memory_key=&quot;chat_history&quot;, return_messages=True ) ) return qa_chain# 运行chatbot = build_doc_chatbot(&quot;./my_documents&quot;)# 对话chat_history = []while True: question = input(&quot;你: &quot;) if question.lower() in [&quot;退出&quot;, &quot;quit&quot;, &quot;exit&quot;]: break result = chatbot(&#123;&quot;question&quot;: question, &quot;chat_history&quot;: chat_history&#125;) print(f&quot;AI: &#123;result[&#x27;answer&#x27;]&#125;&quot;) chat_history.append((question, result[&#x27;answer&#x27;])) 总结LangChain为LLM应用开发提供了标准化框架，其核心组件（Models、Prompts、Chains、Agents、Memory、Retrieval）覆盖了从简单调用到复杂代理的全场景需求。RAG模式解决了LLM知识时效性问题，Agent模式赋予了LLM工具使用能力，这两者是构建LLM应用的基石。

Prompt Engineering技巧与最佳实践随着ChatGPT等大模型的普及，Prompt Engineering成为2022年最热门的AI技能。如何编写有效的提示词来引导大模型产生高质量输出，已成为一门重要的工程学科。 1. Prompt Engineering的核心原则1.1 基本原则graph TB A[有效的Prompt] --> B[清晰明确] A --> C[上下文充足] A --> D[示例驱动] A --> E[结构化输出] A --> F[迭代优化] 1.2 Prompt构成要素一个完整的Prompt通常包含以下部分： 1[角色设定] + [背景上下文] + [任务描述] + [输出格式] + [约束条件] + [示例] 123456789101112131415161718192021222324252627282930313233343536373839# 使用OpenAI API的Prompt工程示例import openaidef structured_prompt(role, context, task, format_spec, constraints, examples=None): &quot;&quot;&quot;构建结构化Prompt&quot;&quot;&quot; messages = [] # 1. 角色设定 system_msg = f&quot;你是一个&#123;role&#125;。&quot; messages.append(&#123;&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: system_msg&#125;) # 2. 构建用户消息 user_parts = [] user_parts.append(f&quot;背景信息：&#123;context&#125;&quot;) user_parts.append(f&quot;任务：&#123;task&#125;&quot;) user_parts.append(f&quot;输出格式：&#123;format_spec&#125;&quot;) user_parts.append(f&quot;约束条件：&#123;constraints&#125;&quot;) if examples: user_parts.append(f&quot;参考示例：
&#123;examples&#125;&quot;) messages.append(&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;

&quot;.join(user_parts)&#125;) return messages# 示例：代码审查Promptmessages = structured_prompt( role=&quot;高级Python开发工程师和代码审查专家&quot;, context=&quot;这是一个数据处理服务的核心模块，需要高可靠性和性能&quot;, task=&quot;审查以下代码，找出潜在的bug、性能问题和安全漏洞&quot;, format_spec=&quot;按严重程度分类：🔴严重 🟡中等 🟢建议，每项包含：问题描述、代码位置、修复建议&quot;, constraints=&quot;1. 重点关注并发安全问题
2. 检查是否有资源泄漏
3. 注意异常处理的完整性&quot;, examples=&quot;输入: def add(a,b): return a+b
输出: 🟢建议: 缺少类型注解和输入验证&quot;)response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo&quot;, messages=messages, temperature=0.3 # 代码审查用低温度) 2. 核心技巧详解2.1 少样本学习（Few-Shot）123456789101112131415161718192021222324def few_shot_prompt(task_description, examples, query): &quot;&quot;&quot;少样本学习Prompt&quot;&quot;&quot; prompt = f&quot;&#123;task_description&#125;

&quot; for example in examples: prompt += f&quot;输入: &#123;example[&#x27;input&#x27;]&#125;
&quot; prompt += f&quot;输出: &#123;example[&#x27;output&#x27;]&#125;

&quot; prompt += f&quot;输入: &#123;query&#125;
输出:&quot; return prompt# 情感分析Few-Shot示例sentiment_examples = [ &#123;&quot;input&quot;: &quot;这个产品太棒了，强烈推荐！&quot;, &quot;output&quot;: &quot;正面&quot;&#125;, &#123;&quot;input&quot;: &quot;质量一般，不太满意&quot;, &quot;output&quot;: &quot;中性&quot;&#125;, &#123;&quot;input&quot;: &quot;完全不能用，浪费钱&quot;, &quot;output&quot;: &quot;负面&quot;&#125;, &#123;&quot;input&quot;: &quot;物流很快，但包装有破损&quot;, &quot;output&quot;: &quot;混合&quot;&#125;,]result = few_shot_prompt( task_description=&quot;请判断以下评论的情感倾向：&quot;, examples=sentiment_examples, query=&quot;服务态度很好，下次还会光顾&quot;) 2.2 Chain-of-Thought（思维链）123456789101112131415161718192021222324def cot_prompt(question): &quot;&quot;&quot;思维链Prompt - 引导模型逐步推理&quot;&quot;&quot; return f&quot;&quot;&quot;请一步步思考以下问题，展示完整的推理过程：问题：&#123;question&#125;请按以下格式回答：1. 理解问题：提取关键信息2. 分析思路：列出解题步骤3. 逐步推理：每步给出详细计算4. 最终答案：简洁明确的结论示例：问题：一个商店打8折后价格是160元，原价是多少？1. 理解问题：已知折扣后价格=160元，折扣率=80%2. 分析思路：原价 × 折扣率 = 折后价，因此原价 = 折后价 / 折扣率3. 逐步推理：原价 = 160 / 0.8 = 200元4. 最终答案：原价是200元&quot;&quot;&quot;# 数学推理math_prompt = cot_prompt( &quot;小明有5个苹果，给了小红2个，又从商店买了3个，最后吃掉了1个。小明现在有几个苹果？&quot;) 2.3 Self-Consistency（自一致性）12345678910111213141516171819202122232425262728293031323334import refrom collections import Counterdef self_consistency_query(question, n_samples=5): &quot;&quot;&quot; 自一致性方法：多次采样取多数投票 适用于需要精确答案的推理任务 &quot;&quot;&quot; prompt = f&quot;&quot;&quot;请一步步思考以下问题，在最后用####标出最终答案。问题：&#123;question&#125;&quot;&quot;&quot; answers = [] for _ in range(n_samples): response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo&quot;, messages=[&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: prompt&#125;], temperature=0.7, # 较高温度增加多样性 max_tokens=500 ) text = response.choices[0].message.content # 提取####后的答案 match = re.search(r&#x27;####\s*(.+)&#x27;, text) if match: answers.append(match.group(1).strip()) # 多数投票 counter = Counter(answers) best_answer = counter.most_common(1)[0] print(f&quot;各次采样答案: &#123;answers&#125;&quot;) print(f&quot;投票结果: &#123;best_answer[0]&#125; (出现&#123;best_answer[1]&#125;次)&quot;) return best_answer[0] 3. 高级技巧3.1 ReAct框架1234567891011121314151617181920212223242526272829303132def react_prompt(question, tools): &quot;&quot;&quot;ReAct: 推理+行动框架&quot;&quot;&quot; tool_descriptions = &quot;
&quot;.join( [f&quot;- &#123;t[&#x27;name&#x27;]&#125;: &#123;t[&#x27;description&#x27;]&#125;&quot; for t in tools] ) return f&quot;&quot;&quot;你是一个能够使用工具的智能助手。可用工具：&#123;tool_descriptions&#125;请按以下格式回答问题：思考：分析当前需要什么信息行动：使用工具获取信息（格式：工具名[参数]）观察：工具返回的结果...（重复思考-行动-观察直到得出答案）回答：最终答案问题：&#123;question&#125;&quot;&quot;&quot;# 使用示例tools = [ &#123;&quot;name&quot;: &quot;Search&quot;, &quot;description&quot;: &quot;搜索互联网获取信息&quot;&#125;, &#123;&quot;name&quot;: &quot;Calculator&quot;, &quot;description&quot;: &quot;进行数学计算&quot;&#125;, &#123;&quot;name&quot;: &quot;Weather&quot;, &quot;description&quot;: &quot;查询天气信息&quot;&#125;,]react_query = react_prompt( &quot;北京今天天气如何？如果下雨，室内活动推荐什么？&quot;, tools) 3.2 结构化输出1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950def structured_output_prompt(data, schema): &quot;&quot;&quot;确保LLM输出结构化数据&quot;&quot;&quot; return f&quot;&quot;&quot;请根据以下数据，按指定JSON Schema生成结果。数据：&#123;data&#125;输出Schema：&#123;schema&#125;要求：1. 严格按照Schema格式输出2. 所有字段都必须填写3. 只输出JSON，不要其他内容4. 确保JSON格式正确可解析示例输出：&#123;&#123;&quot;name&quot;: &quot;张三&quot;, &quot;age&quot;: 25, &quot;skills&quot;: [&quot;Python&quot;, &quot;ML&quot;]&#125;&#125;&quot;&quot;&quot;# 实际使用import jsonresume_text = &quot;&quot;&quot;张三，男，28岁5年Python开发经验，3年机器学习经验精通PyTorch、TensorFlow参与过3个大型推荐系统项目&quot;&quot;&quot;schema = &#123; &quot;type&quot;: &quot;object&quot;, &quot;properties&quot;: &#123; &quot;name&quot;: &#123;&quot;type&quot;: &quot;string&quot;&#125;, &quot;age&quot;: &#123;&quot;type&quot;: &quot;integer&quot;&#125;, &quot;skills&quot;: &#123;&quot;type&quot;: &quot;array&quot;, &quot;items&quot;: &#123;&quot;type&quot;: &quot;string&quot;&#125;&#125;, &quot;experience_years&quot;: &#123;&quot;type&quot;: &quot;integer&quot;&#125;, &quot;projects&quot;: &#123;&quot;type&quot;: &quot;integer&quot;&#125; &#125;&#125;response = openai.ChatCompletion.create( model=&quot;gpt-3.5-turbo&quot;, messages=[&#123; &quot;role&quot;: &quot;user&quot;, &quot;content&quot;: structured_output_prompt(resume_text, json.dumps(schema)) &#125;], temperature=0)result = json.loads(response.choices[0].message.content) 4. Prompt模板管理1234567891011121314151617181920212223242526272829303132class PromptTemplate: &quot;&quot;&quot;可复用的Prompt模板管理&quot;&quot;&quot; def __init__(self): self.templates = &#123;&#125; def register(self, name, template, variables): &quot;&quot;&quot;注册模板&quot;&quot;&quot; self.templates[name] = &#123; &quot;template&quot;: template, &quot;variables&quot;: variables &#125; def render(self, name, **kwargs): &quot;&quot;&quot;渲染模板&quot;&quot;&quot; template = self.templates[name] missing = set(template[&quot;variables&quot;]) - set(kwargs.keys()) if missing: raise ValueError(f&quot;缺少变量: &#123;missing&#125;&quot;) return template[&quot;template&quot;].format(**kwargs)# 注册常用模板pm = PromptTemplate()pm.register( name=&quot;code_explain&quot;, template=&quot;&quot;&quot;请解释以下&#123;language&#125;代码的功能：```&#123;language&#125;&#123;code&#125; 要求： 先概述整体功能 然后逐段解释关键逻辑 最后说明输入输出格式 指出潜在的改进点”””, variables&#x3D;[“language”, “code”]) pm.register( name&#x3D;”bug_fix”, template&#x3D;”””以下{language}代码存在bug： 1&#123;code&#125; 错误信息：{error_msg} 请： 分析bug原因 提供修复方案 解释为什么修复有效 建议如何避免类似问题”””, variables&#x3D;[“language”, “code”, “error_msg”]) 使用模板prompt &#x3D; pm.render( “code_explain”, language&#x3D;”Python”, code&#x3D;”def quicksort(arr): return arr if len(arr)&lt;&#x3D;1 else quicksort([x for x in arr[1:] if x&lt;&#x3D;arr[0]]) + [arr[0]] + quicksort([x for x in arr[1:] if x&gt;arr[0]])”) ## 5. Prompt优化策略 &lt;pre class=&quot;mermaid&quot;&gt;graph TD A[初始Prompt] --&gt; B[测试评估] B --&gt; C&#123;效果如何?&#125; C --&gt;|好| D[记录最佳版本] C --&gt;|差| E[分析失败原因] E --&gt; F[调整Prompt] F --&gt; B D --&gt; G[A/B测试不同版本] G --&gt; H[选择最优版本]&lt;/pre&gt; ### 优化检查清单 | 维度 | 检查项 | 优化方向 | |------|--------|----------| | 清晰度 | 是否有歧义 | 更精确的措辞 | | 上下文 | 背景是否充分 | 补充领域知识 | | 示例 | Few-shot是否有效 | 增加多样性示例 | | 格式 | 输出是否一致 | 明确格式要求 | | 约束 | 是否有违规输出 | 添加负面约束 | | 温度 | 创造性vs准确性 | 调整temperature | ## 总结 Prompt Engineering是大模型时代的关键技能。通过掌握Few-Shot、CoT、ReAct等技巧，并建立模板管理和迭代优化流程，可以显著提升大模型的输出质量。这不是临时技巧，而是一门需要持续学习和实践的工程学科。

