e(seq_len): start = max(0, i - self.window_size) mask[i, start:i+1] = 1 # 跨层次连接 for i in range(0, seq_len, self.stride): for j in range(i, min(i + self.stride, seq_len)): mask[j, i] = 1 if i + self.stride &lt; seq_len: mask[j, i + self.stride] = 1 return mask.bool() Few-Shot学习能力GPT-3的核心能力是在不进行梯度更新的情况下通过提示进行学习： 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051class FewShotPrompt: &quot;&quot;&quot;Few-shot提示生成&quot;&quot;&quot; def __init__(self, model, tokenizer): self.model = model self.tokenizer = tokenizer def generate(self, task_description, examples, query): &quot;&quot;&quot; 生成few-shot提示 Args: task_description: 任务描述 examples: [&#123;&quot;input&quot;: &quot;...&quot;, &quot;output&quot;: &quot;...&quot;&#125;] query: 查询输入 &quot;&quot;&quot; # 构建提示 prompt_parts = [task_description] for ex in examples: prompt_parts.append(f&quot;Input: &#123;ex[&#x27;input&#x27;]&#125;&quot;) prompt_parts.append(f&quot;Output: &#123;ex[&#x27;output&#x27;]&#125;&quot;) prompt_parts.append(f&quot;Input: &#123;query&#125;&quot;) prompt_parts.append(&quot;Output:&quot;) prompt = &quot;
